/* Regeln – Storm and Root, Kapitel 1 „Das Wilde Blau“: Regeln (S&R S. 18–39), deutscher Buchtext */
window.WS_NACH = window.WS_NACH || {}; WS_NACH.regeln = WS_NACH.regeln || [];
(function(L){ var K = "Das Wilde Blau";
L.push({id:"sr-blau-regeln-ueberblick", k:K, t:"Regeln des Wilden Blaus", p:18, q:"sr", b:[
 {box:"Regeln des Wilden Blaus", x:["Die restlichen Seiten dieses Kapitels behandeln Mechaniken rund um Flug und den offenen Himmel und bauen auf den bereits eingeführten erzählerischen Elementen auf. Kurz gesagt behandeln diese Seiten …","· Flug: In mehrere Abschnitte gegliedert, die die Start- und Flugstile erläutern, die für das Reisen durch die Luft wichtig sind, sowie Informationen zu Flugmanövern, Landungen und den Auswirkungen von Wetter- und Umgebungslagen.","· Reisen durch das Wilde Blau: Mit einer neuen Wachtabelle, zusätzlichen Optionen für Charaktere am Steuer und neuen Systemen zum Ankerwerfen oder Treiben in der Luft. Dieser Abschnitt enthält außerdem eine neue Position, die Charaktere während einer Reise einnehmen können, Ärger suchen, die ihnen erlaubt, Vorzeichen und Omen zu gefährlichen, aber einträglichen Begegnungen zusammenzusetzen.","· Aufmerksamkeit: Ein neues System für jene, die den Himmeln zusätzliche Gefahr bringen wollen. Der Abschnitt Aufmerksamkeit führt das Konzept der Beobachter und die Leiste der Wachsamen Augen ein, die deren Aufmerksamkeit überwacht."]},
 {box:"Weiterführende Lektüre …", x:["Neben dem mechanischen Abschnitt dieses Kapitels solltest du für das beste Verständnis der Regeln die Besonderheiten von … durchsehen","· Auftriebssysteme: Die Wege, ein wellenschneidendes Schiff mit einem Maß an Sicherheit in die Luft zu bringen, zu finden auf S. 112 im Kapitel zum Schiffsbau.","· Ablenker: Ein optionales, aber äußerst nützliches Extra; Ablenker erlauben einer Crew, einen Beobachter von oben oder unten … vorübergehend abzuwehren oder abzulenken."]},
 {h:"Flug"},
 {a:"Wie die meiste andere Bewegung in der Wildsee wird Flug für Charaktere und Luftschiffe gleichermaßen im „Kopfkino“ abgehandelt – es gibt keine Regeln für genaue Fluggeschwindigkeit oder wie scharf jemand wenden kann, denn solche Kleinigkeiten stehen dem Erzählen einer guten Geschichte am Tisch meist im Weg. Aber das heißt nicht, dass es keine Regeln zu beachten gäbe! Die Mechanik des Fliegens ist in Stile gegliedert, besondere Schlüsselwörter, die einem Spieler sagen, wie sich sein Schiff oder Charakter in der Luft verhält. Die Stile teilen sich in zwei Gruppen: Startarten und Flugstile. Stile tauchen sowohl in Aspekten rund ums Fliegen als auch in Auftriebssystemen von Luftschiffen auf."},
 {a:"Wenn du diese beiden Stilgruppen verstehst, kannst du mit Schiff oder Charakter selbstbewusst in die Luft steigen, auch wenn es ein paar zusätzliche Regeln zu beachten gibt, die speziell für Luftschiffe gelten (besonders bei Reisen)."},
 {a:"Dieser Abschnitt behandelt außerdem atmosphärische Elemente, die ein Glühwürmchen nutzen kann, um das Fliegen für Schiffe und Crew leichter oder schwerer zu machen, sowie Ratschläge zum Anordnen von Würfen und zum Umgang mit flugbezogenem Schaden."}
]});
L.push({id:"sr-blau-startarten", k:K, t:"Startarten", p:19, q:"sr", b:[
 {a:"Die ersten Momente eines Flugs sind in gewisser Weise die wichtigsten. Sie sind vielleicht auch die gefährlichsten. Wenn ein Schiff oder Charakter abhebt, lässt er die Sicherheit festen Bodens hinter sich. Für Charaktere ist es so einfach, dass der Spieler dem Rest des Tischs mitteilt, dass er in die Luft steigt. Für Schiffe ist es nicht ganz so einfach – es ist gut möglich, dass der Vorgang die Werte des Schiffs beschädigt. Mehr über das Schadenspotenzial für Werte erfährst du weiter unten auf dieser Seite, aber merke dir für den Moment, dass auf den Wellen fast alles aus Schrott, Hoffnung und Einfallsreichtum gemacht ist – Luftschiffe eingeschlossen."},
 {a:"Charaktere erhalten eine Startart durch einen Aspekt (oder durch einen vorübergehenden Vorteil), Luftschiffe durch ihr Auftriebssystem (eine Komponente, die beim Bau eines Luftschiffs nötig ist). Doch ob Schiff oder Charakter, was immer dir die Kraft des Fliegens verleiht, legt eine der beiden nachfolgend beschriebenen Startarten fest …"},
 {c:"Auftrieb (Float)", x:"Am häufigsten erreicht durch: Ballons, Insektenflügel, Arconautik\nKernpunkte: Erlaubt einen Start ohne jeden Vorwärtsschwung, die Fähigkeit, senkrecht in die Himmel aufzusteigen (und auf dieselbe Weise abzusteigen)."},
 {c:"Anlauf (Rush)", x:"Am häufigsten erreicht durch: Raketen, gefiederte Flügel, Luftsegel\nKernpunkte: Erlaubt einen Start, wenn der Charakter oder das Schiff Schwung hat, sei es durch Laufen, durch Gleiten über die Wellen oder durch einen Sprung von einer Klippe."},
 {a:"Beispiel: Klyka ist eher ein Rattlehand als ein Aeronaut, aber er hat es geschafft, an ein paar Ballons zu kommen, die leichter als Luft sind. Sie an einem Gurtzeug so zu befestigen, dass es sich nicht beängstigend anfühlte, hat die halbe Nacht gedauert, doch als die Morgendämmerung anbricht, ist er bereit, sie auszuprobieren. Der vorübergehende Aspekt, den er durch seine Konstruktion erhält, gibt ihm die Startart Auftrieb, sodass er jederzeit sanft vom Boden abheben kann."},
 {a:"Beispiel: Die Stinking Remora ist ein einfaches Luftschiff, ein umgebauter Wellenschneider mit einem Satz Brute Turbines am Heck. Wenn die Crew ein Startmanöver ausführen will, beginnt sie damit, auf den Wellen Geschwindigkeit aufzunehmen – mit genug Strecke und Schwung geben die Turbinen ihr den nötigen Auftrieb, um die Äste hinter sich zu lassen."},
 {a:"Es ist möglich, dass ein Schiff oder Charakter Zugang zu Auftrieb und Anlauf zugleich hat, wenn er passende Aspekte oder Auftriebssysteme besitzt. Beides zu haben ist ein gewaltiger Vorteil, der Bruchlandungen und unbeholfene Starts weit unwahrscheinlicher macht."},
 {h:"Würfe für Starts"},
 {a:"Abzuheben ist eine Aktion wie jede andere: Ob du würfeln musst, um in die Himmel zu gelangen, hängt ganz von der Situation ab. Die Regeln hier folgen dem Wildsee-Standard – wenn der Start schwierig, gefährlich oder dramatisch ist, erfordert er wahrscheinlich einen Wurf."},
 {a:"Für Charaktere ist das ein Aktionswurf. Das Abheben von den Wellenspitzen könnte durch die Fertigkeit Springen oder Wellenlauf unterstützt werden, und Glänzen könnte zu beeindruckenden Arten führen, den festen Boden zu verlassen. Für manche Charaktere könnten auch Abfangen oder Spüren nützlich sein – besonders für jene, die sich erzählerisch darauf verlassen, eine Windböe oder Schwankung magnetischer Felder zu erwischen."},
 {a:"Für Schiffe ist ein Wertewurf angemessener. Tempo eignet sich am besten für Luftschiffe mit dem Stil Anlauf, Neigung für jene mit dem Stil Auftrieb, doch das sind nur Richtlinien – ein Start durch ein Feld überhängender Äste könnte einen Spieler zum Beispiel die Panzerung seines Schiffs würfeln lassen."},
 {h:"Startkosten"},
 {a:"Auch wenn ein Start bei schlechten Bedingungen einen Wurf erfordern kann, fallen für die Mehrheit der Wildsegler keine zusätzlichen Kosten an. Luftschiffe sind jedoch eine andere Geschichte. Selbst für das bestgebaute himmelstaugliche Fahrzeug ist der Start ein gefährliches Unterfangen. Ein Schiff zerlegt sich vielleicht nicht völlig, aber ein gewisser Schaden ist zu erwarten. Deshalb hat jedes Luftschiff-Auftriebssystem Startkosten, einen bestimmten Wert, der jedes Mal beeinträchtigt wird, wenn sich das Schiff in die Lüfte erhebt."},
 {a:"Der Start fügt diesem Wert selbstverständlich eine Markierung Schaden zu, unabhängig von den atmosphärischen Bedingungen."},
 {a:"Beispiel: Die Salmon Run bereist das Wilde Blau mit Canvas Wings, einem Auftriebssystem, das die Startart Anlauf gibt. Die Startkosten für Canvas Wings sind Tempo, was bedeutet, dass das Schiff eine Markierung Schaden auf seinem Tempo-Wert nimmt, wenn es in die Himmel hinaufruckt."},
 {a:"Ist ein Start besonders schwierig, nimmt das Schiff vielleicht auch an einem anderen Wert Schaden, oder an der Fracht, oder an den Wildseglern, die es trägt. Das kommt meist ins Spiel, wenn ein Schiff wegen widriger atmosphärischer Elemente einen Wertewurf machen muss und mit einem Konflikt oder Desaster endet (ein Desaster verhindert normalerweise auch, dass das Schiff überhaupt abhebt). Mehr über diese atmosphärischen Elemente erfährst du auf S. 24, und S. 23 bietet eine Methode, Startkosten in der richtigen Situation zu vermeiden."}
]});
L.push({id:"sr-blau-flugstile", k:K, t:"Flugstile", p:20, q:"sr", b:[
 {erz:"Wir fliegen nach den Sternen, nach den Mustern, die sie weben, den gefrorenen und den ziehenden und den pulsierenden Lichtern oben.\nWir fliegen nach den Winden, nach dem Atem der Himmel, dem wolkenschaufelnden, segelreißenden, sturmhütenden Heulen des Blaus.\nWir fliegen nach den Vögeln, nach den Pfaden, die sie schlagen, durch Aufwind und Käferschnapp und Quersprung und Stil.\nUnd wir fliegen nach den Wellen, nach den Bäumen weit unten, der Astdünung und Blütenflut, die uns in der Jugend hielt.\nDie Bäume sind ein Meer …\nAber die Himmel sind ein Ozean."},
 {a:"Wenn du erst einmal in der Luft bist, wird es leichter, so versichern die selbstsichereren Aeronauten nervösen Neulingen."},
 {a:"Die Art, wie du fliegst, sobald du in der Luft bist, wird durch ein zweites Schlüsselwort bestimmt, das Flugstil genannt wird. Es gibt vier davon, und wie bei den Startarten funktionieren sie praktisch gleich, ob sie von einem einzelnen Wildsegler oder einem ganzen Luftschiff genutzt werden. Der einzige Unterschied liegt bei Reisen – bestimmte Flugstile erlauben es, in der Luft bestimmte Aktionen zu nutzen, etwa Anker werfen oder Vorwärtspreschen. Diese Informationen finden sich in den jeweiligen Kästen unten."},
 {a:"Flugstile werden wie Startarten entweder durch einen Aspekt, einen vorübergehenden Vorteil oder ein Auftriebssystem erlangt. Die angebotenen Flugstile sind …"},
 {c:"Gleiten (Glide)", x:"Am häufigsten erreicht durch: Starrflügel-Aufsätze, Fallschirme, Luftsegel\nKernpunkte: Erlaubt sanfte Luftbewegung und anmutige Abstiege, doch du kannst keine Höhe gewinnen, ohne dass ein Umweltfaktor zu deinen Gunsten wirkt (etwa ein nützlicher Aufwind, eine praktische Thermik oder die Hitze eines Sporenschlots auf Wellenhöhe).\nZusätzliche Mechanik für Luftschiffe: Gleiten erlaubt einem Fahrzeug, durch die Luft zu reisen, ohne dass seine Motoren laufen. Es erlaubt Schiffen außerdem, in der Luft Pfad schneiden zu nutzen und so stetig auf Reisen voranzukommen."},
 {c:"Schweben (Hover)", x:"Am häufigsten erreicht durch: Rotorblätter, verankerte Geister, magnetische Kräfte, Ballons\nKernpunkte: Erlaubt Bewegung in etwa Gehgeschwindigkeit in der Luft. Wichtiger noch: Schweben erlaubt einem Nutzer, ohne Bewegung oder Schwung in der Luft zu bleiben und ohne jede äußere Stütze am Himmel zu hängen. Starke Winde können ein schwebendes Schiff oder Individuum allerdings immer noch durchschütteln oder versetzen.\nZusätzliche Mechanik für Luftschiffe: Auch wenn es nicht schnell genug ist, um auf einer Reise durch das Wilde Blau nennenswert voranzukommen, erlaubt Schweben einem Fahrzeug, Anker zu werfen, ohne vorher zu landen, sodass die Crew auf längeren Luftreisen rasten kann. Dies erlaubt auch die Nutzung der neuen Reiseaktion Treiben, beschrieben auf S. 27."},
 {c:"Flattern (Flap)", x:"Am häufigsten erreicht durch: Natürliche Flügel, mechanische Aufsätze\nKernpunkte: Es mag etwas unbeholfen sein, aber es ist verlässlich; deine Luftbewegung beruht auf ständiger Anstrengung und wiederholten Bewegungen, meist in Form schlagender Flügel (obwohl eine wellenförmige Bewegung oder ein wiederholter mechanischer Impuls dieselbe Wirkung haben). Du kannst kontrolliert auf- und absteigen und Flugmanöver ausführen, wirst damit aber wohl keine Wettbewerbe gewinnen. Du musst dich in der Luft außerdem in Bewegung halten (es sei denn, du hast etwas anderes, das dich an einer Stelle bleiben lässt, etwa die Fähigkeit zu Schweben).\nZusätzliche Mechanik für Luftschiffe: Flattern erlaubt einem Fahrzeug, in der Luft Pfad schneiden zu nutzen, sodass es auf Reisen durch das Wilde Blau ordentlich vorankommt."},
 {c:"Schwingen (Soar)", x:"Am häufigsten erreicht durch: Luftstrahlen, Raubvogel-Flügel, chemische Katalysatoren\nKernpunkte: Der Höhepunkt des Fliegens – du kannst mit Tempo und Stil aufsteigen, absteigen und Flugmanöver ausführen. Du musst dich in der Luft außerdem in Bewegung halten (es sei denn, du hast etwas anderes, das dich an einer Stelle bleiben lässt, etwa die Fähigkeit zu Schweben).\nZusätzliche Mechanik für Luftschiffe: Schwingen erlaubt einem Fahrzeug, in der Luft sowohl Pfad schneiden als auch Vorwärtspreschen zu nutzen, was Crews auf Reisen durch das Wilde Blau ebenso viel Kontrolle gibt wie auf den Wellen darunter."}
]});
L.push({id:"sr-blau-flug-details", k:K, t:"Fliegen im Detail", p:21, q:"sr", b:[
 {h:"Besonderheiten der Flugstile"},
 {a:"Auch wenn ihre Einzelheiten verschieden sind, erlaubt jeder der Flugstile einem Charakter oder Schiff, irgendwie durch das Wilde Blau voranzukommen."},
 {a:"Beispiel: Moranir nutzt sein Drachensegel, um über die Wellen zu einem fernen Piratenschiff zu gelangen. Der Aspekt seines besonderen Drachensegels gibt ihm den Flugstil Schwingen, sodass er sich in beeindruckendem Tempo über die Wellen auf sein Ziel zubewegt."},
 {a:"Beispiel: Die Dogged Courage ist kein beeindruckendes Luftschiff in Sachen Geschwindigkeit, aber ein verlässliches altes Schlachtross. Die installierten Auftriebssysteme geben ihr Zugang zu Flattern und Schweben, sodass die Crew auf Reisen nach Herzenslust Pfad schneiden und rasten kann, indem sie Anker wirft, ohne je aufsetzen zu müssen."},
 {h:"Flugstile ausschmücken"},
 {a:"Ob du gleitest, schwebst, flatterst oder schwingst, der erzählerische Teil des Fliegens liegt ganz beim Tisch. Von einem Charakter mit dem Flugstil Gleiten könnte man annehmen, dass er sich mit einem Hauch Anmut bewegt, doch defekte Repulsor-Mechanismen könnten dasselbe mechanische Ergebnis haben (Kontrolle über Luftbewegung und Abstieg) ohne jede damit verbundene Eleganz. Wie bei jedem anderen Aspekt, Vorteil oder Auftriebssystem darfst du sie gern an deinen Tisch und den Ton deines Spiels anpassen."},
 {a:"Beispiel: Leth kombiniert zwei ihrer Aspekte und will einen „natürlicheren“ Weg, in die Luft zu kommen. Ihr Charakter ist ein Thorn, ein Meister des Pflanzenlebens, also kombiniert sie einen der ranken-basierten Aspekte des Thorns mit dem starren Drachensegel. Der entstehende Aspekt gibt ihr den Flugstil Gleiten, ist aber nicht ausrüstungsbasiert, sondern als wirbelnde Ranken ausgeschmückt, die ihr einen hubschrauberartigen Effekt geben, wenn sie aus der Höhe hinabsteigt."},
 {h:"Würfe für Flug"},
 {a:"Sobald du in der Luft bist, übernehmen Schwung und Übung. Du musst vielleicht würfeln, um ein kompliziertes oder gefährliches Flugmanöver auszuführen (mehr dazu auf der nächsten Seite), aber das bloße Kommen von A nach B in der Luft erfordert keinen Wurf. … Normalerweise. Wie bei jeder anderen Aktion kann Bewegung durch die Luft durchaus einen Aktions- oder Wertewurf erfordern, wenn die Situation schwierig, dramatisch oder gefährlich ist. Den Gipfel eines Vulkans zu erreichen, wird zum Beispiel plötzlich weit intensiver, wenn er überhitzte Gase speit."},
 {a:"Beispiel: Gramish versucht, sich durch einen Sturm zu kämpfen, von einer Hochhafen-Landebahn zu einem nahen Ladekran. Das Glühwürmchen verlangt von ihm einen Wurf mit Abzug für den Start, den er schafft, doch tatsächlich voranzukommen, sobald seine Flügel ihn vom Boden gezogen haben, ist eine andere Geschichte. Der nächste Wurf, für die Bewegung von der Fläche über der Landebahn zum Kran, endet in einem Desaster – er wird zurückgeblasen, von den Winden weiter von seinem Ziel weggepeitscht."},
 {h:"Die Anstrengung des Fliegens"},
 {a:"Eine kleine, aber wichtige Konvention – wenn du als Wildsegler lange fliegst, besonders wenn dein Flug von deinen eigenen Muskeln angetrieben wird, wirst du erschöpft. Übermäßiges Fliegen kann dazu führen, dass das Glühwürmchen dich bittet, den Aspekt oder Vorteil zu markieren, der dir die Fähigkeit verleiht, oder Würfelwürfe und Abzug für Aktionen verhängt, die normalerweise kein Problem darstellen würden."},
 {bsp:"Flug im Spiel", z:[
  ["Inge","Ich prüfe das Gurtzeug und die Griffe des Drachensegels. Sieht das Ding sicher aus?"],
  ["Glühwürmchen","Nicht im Geringsten, aber im Moment ist es die einzige Option, die du hast."],
  ["Inge","Stellar. In dem Fall werfe ich meinen Gefährten einen Blick zu, der vielleicht der letzte ist, und beginne meinen Anlauf zur Schiffsseite – ich versuche, diesen Sporenschlot an Backbord zu nutzen, um etwas Höhe zu gewinnen und es zur Spitze der Mesa zu schaffen."],
  ["Todd","Ohne in diese Dornen zu krachen."],
  ["Inge","Das war definitiv mitgemeint. Anlauf und Gleiten – ich würfle dafür, richtig?"],
  ["Glühwürmchen","Das tust du in der Tat. Sobald du richtig in der Luft bist, wird es leichter für dich, aber ich gebe dir einen Abzug von eins, um dich von der Reling zu stoßen und den Auftrieb von diesem Schlot zu erwischen."],
  ["Inge","Nun, das sind 1W6 von Anmut, 2W6 von meiner Fertigkeit Glänzen, und das Drachensegel gibt einen Würfel dazu … 4W6 ergeben … Eine 6! Nein, es gibt einen Abzug. Verdammt … Eine 5! Immer noch ziemlich gut!"],
  ["Glühwürmchen","Definitiv gut genug – die Sporen aus dem Schlot fangen die Unterseite des Drachensegels und schicken dich in die Luft, aber du bekommst dabei eine ordentliche Lunge voll davon ab. Markiere einen Punkt Gift-Schaden, aber du bist in der Luft!"],
  ["Inge","Gut, ich richte mich auf das Plateau der Mesa aus und mache so viel Strecke wie möglich, bevor ich zu sinken beginne."],
  ["Kyllian","Ich glaube, das ist der Punkt, an dem ich an ihr vorbeizische, ehrlich gesagt – ich habe noch diese vorübergehende Eigenschaft von den Fledermausflügel-Gebräuen, also markiere ich diese Leiste für einen Schub der Stile Auftrieb und Schwingen. Ich fliege auch zur Mesa und winke im Vorbeiflug."],
  ["Inge","Das hättest du nicht erwähnen können, bevor ich vom verdammten Schiff gesprungen bin?"]
 ]}
]});
L.push({id:"sr-blau-flugmanoever", k:K, t:"Flugmanöver", p:22, q:"sr", b:[
 {a:"Wenn die Fähigkeit zu fliegen nicht schon genug zum Angeben ist, kannst du immer noch durch gefährliche Flugmanöver mitten in der Luft beeindrucken und verblüffen. Oder vielleicht gibt es einen praktischeren Zweck – eine Korkenzieherrolle mag protzig wirken, kann aber auch der beste Weg sein, einem anfliegenden chemischen Geschoss auszuweichen."},
 {a:"Beispiel: Hewitt hat einen Aspekt Wolkendraht, ein beeindruckendes Stück Ausrüstung, das ihn dank dünner Filamentdrähte ferne Wolken als Flughilfe nutzen lässt. Er will einem Dorf potenzieller Fans etwas vorführen und beschließt deshalb, drahtunterstützte Räder zu schlagen. Er macht einen Aktionswurf mit seiner Stärke Anmut, der Fertigkeit Springen und einem Vorteil durch den Wolkendraht. Die akrobatische Darbietung beeindruckt die Menge und bringt ihm ein paar glühende Anhänger ein."},
 {a:"Es gibt keine feste Liste von Manövern, die ein Charakter oder Schiff in der Luft ausführen kann – sie sind in erster Linie fürs Kopfkino, wie jede andere Form beeindruckender Bewegung. Beschreibe die Kunststücke, die du versuchst, so, wie du glaubst, dass sie aussähen, und lass das Glühwürmchen die Würfel ins Spiel bringen oder Abzug verhängen, wie es das in jeder anderen Situation täte."},
 {h:"Würfe für Flugmanöver"},
 {a:"Manöver und komplexe Bewegungen erfordern in fast allen Situationen einen Wurf, anders als allgemeine Luftbewegung. Sie sind schließlich von Natur aus dramatisch! Wichtig ist aber: Werden sie als Teil einer Aktion genutzt, um etwas anderes zu tun (etwa im Kampf anzugreifen oder zu verteidigen), gibt es keinen zusätzlichen Malus und keine zusätzlichen Schritte."},
 {a:"Beispiel: Vessa ist in der Luft, aber nicht im Wilden Blau – sie flitzt zwischen den Ästen des Gestrüpps in heißer Verfolgung eines Springfuchses. Das Glühwürmchen sagt ihr, dass sie sich einem dornigen Dickicht aus Ranken nähert, und fragt, was sie tun wird. Aus Angst, ihre Beute zu verlieren, entscheidet sie sich, direkt hindurchzupflügen und ein spiralförmiges Manöver auszuführen, um so viel Tempo wie möglich zu behalten. Das Glühwürmchen überlegt kurz und verlangt dann einen Aktionswurf, mit zusätzlichem Abzug wegen der erhöhten Gefahr."},
 {h:"Luftschiff-Manöver"},
 {a:"Ohne sich auf Äste für Halt oder Auftrieb verlassen zu müssen, haben Luftschiffe ein weit beeindruckenderes Bewegungsspektrum als traditionelle wellenschneidende Fahrzeuge. Bei guten Bedingungen sind Fassrollen, Loopings und schwindelerregende Sturzflüge selbst für einen durchschnittlichen Piloten machbar. Luftschiff-Manöver erfordern einen Wertewurf, um erfolgreich zu sein, nach denselben Regeln wie Manöver für Solo-Flieger."},
 {a:"Meist ist es der Charakter am Steuer, der Manöver einleitet, doch manche können auch den Maschinenraum oder das Deck betreffen. Wichtig ist: Wenn du für ein Manöver würfelst, bedeutet ein Ergebnis von Konflikt oder Desaster nicht von sich aus einen Absturz. Du könntest das Manöver ganz gut hinbekommen, aber den gewünschten Effekt verfehlen. Oder du könntest Schiff, Crew oder Fracht extremen oder zerstörerischen Kräften aussetzen, entweder durch Geschwindigkeit oder durch eine Kollision in der Luft. Das könnte Fracht, Crew oder sogar das Schiff selbst beschädigen."},
 {a:"Die Werte Neigung und Tempo sind deine erste Wahl für luftschiffbasierte Manöver, doch manche Manöver könnten sich mehr auf Panzerung, Tarnung, Sägen oder sogar Dichtung stützen, um korrekt ausgeführt zu werden."},
 {a:"Beispiel: Die Crew der Salmon Run versucht, einem verfolgenden Schiff durch eine Wolkenbank zu entkommen. Zuerst versuchen sie es mit Tarnung, sinken schnell ab, um sich zu verstecken, und das Glühwürmchen verlangt einen Wertewurf auf Tarnung ohne Abzug – die Bedingungen sind perfekt für diese Art Wurf, da die Wolken ausgezeichnete potenzielle Deckung bieten. Ein unglücklicher Wurf lässt sie ungeschützt, als der Wind die Wolkenlandschaft verschiebt, doch die Crew reagiert schnell – sie zieht das Schiff in einen scharfen Steigflug und geht noch weiter, schlägt einen Looping, um hinter ihren Verfolgern zu landen. Das ist ein weit kniffligeres Manöver, und das Glühwürmchen verlangt einen Wurf mit Abzug von zwei und schlägt Neigung vor."},
 {a:"Aktionswürfe für Flugmanöver lassen sich leicht durch die Fertigkeiten Glänzen oder Springen verstärken, vielleicht sogar durch Abfangen oder Wellenlauf, wenn die Bedingungen stimmen."},
 {h:"Leichtsinn und zerbrechliche Fracht"},
 {a:"Manchmal gibt es angesichts eines anfliegenden Angriffs nichts Besseres, als die Crew zu verdammen und das Schiff an seine Grenzen zu treiben – sicher, es gibt vielleicht später etwas zu flicken, aber wenigstens gibt es ein Später. In diesen Situationen kann ein Spieler das Glühwürmchen bitten, seinen Leichtsinn zu berücksichtigen und den Abzug auf einem Wurf zu verringern, im Austausch für Schaden an etwas im Schiff, verursacht durch das Manöver selbst. Das könnte sein …"},
 {l:["Ein Stück Fracht, das an der Wand des Laderaums zerschellt","Ein Crewmitglied, das leichten oder mittleren Stumpf-Schaden nimmt, weil es herumgeschleudert oder von unerwarteter Beschleunigung getroffen wird","Ein Passagier oder Mitglied der Unterbesatzung, das über Bord geworfen wird"]},
 {a:"Beispiel: Der Pilot der Salmon Run hält nicht viel von diesem Abzug von zwei, da ihr Neigungs-Wert nicht der höchste ist. Er fragt, ob er das Manöver leichtsinnig ausführen kann, und das Glühwürmchen stimmt zu – sie können das Schiff über seine Grenzen hinaus treiben und etwas Schaden für die Crew riskieren. Der Pilot wählt diese Option (mit dem Segen aller am Tisch) und wirft das Schiff in einen brutalen Steigflug. Es klappt, aber die Crew nimmt Schaden – ein Charakter im Maschinenraum nimmt Säure-Schaden, weil der Motor überläuft, und die übrigen nehmen eine Markierung Stumpf-Schaden, weil sie in der Kabine herumgeschleudert werden."}
]});
L.push({id:"sr-blau-landungen", k:K, t:"Landungen", p:23, q:"sr", b:[
 {a:"Und du dachtest, in die Luft zu kommen sei schwer … Die Startart eines Schiffs oder Charakters gibt zugleich Auskunft darüber, wie er am bequemsten landet. Etwas mit dem Stil Auftrieb kann meist wieder zur Landung hinabschweben, und etwas mit dem Stil Anlauf muss sowohl die Geschwindigkeit verringern als auch den Boden oder die Wellen treffen, ehe es zum Stehen kommt. Es gibt keine inhärenten Kosten oder Schäden bei der Landung, solange nichts schiefgeht."},
 {h:"Würfe für Landungen"},
 {a:"Wie Starts erfordern Landungen bei weniger als perfekten Bedingungen einen Wurf. Ein Konflikt oder Desaster-Ergebnis kann hier Leisten markieren, Fracht oder Ressourcen beschädigen oder sogar den Charakter oder das Schiff über das erwartete Landegebiet hinausschießen lassen."},
 {a:"Beispiel: Die Salmon Run hat einen ordentlichen Flug hinbekommen, aber alles Gute geht zu Ende. Bei perfekten Bedingungen (etwa günstigem Wind oder einer glatt geschnittenen Landebahn) nimmt das Schiff vielleicht gar keinen Schaden und kommt mit minimalem Aufwand zum Stehen. Sind die Bedingungen schlechter oder ist der Landeplatz mit Hindernissen oder anderen Gefahren übersät, ist es eine andere Geschichte – die meisten Landungen dieser Art rütteln zumindest die Fracht der Salmon Run durch oder verpassen der Crew einen ordentlichen Schrecken."},
 {a:"Wenn Solo-Aeronauten für die Landung würfeln, können sie von Abfangen, Springen oder Wellenlauf profitieren. Luftschiffe verlassen sich wahrscheinlich auf Neigung, wenn sie behutsam landen, auf Panzerung bei einem schweren Aufprall oder sogar auf Sägen, wenn sie landen und dabei Tempo halten wollen."},
 {h:"Bruchlandungen"},
 {a:"Die Umstände im Wilden Blau können sich im Nu ändern, und Landungen sind nicht immer geplant. Eine Landung, die nicht zur eigenen Startart passt, zählt als Bruchlandung und verursacht stets Schaden irgendeiner Art. Wie jede andere harte Landung kann das die Form von Schaden an Leisten, Werten, Ressourcen oder Fracht oder einer bleibenden Verletzung haben. Die Einzelheiten liegen in diesen Situationen beim Glühwürmchen. Selbst ein Triumph kann diesen zusätzlichen Nachteil nicht vermeiden – das Schiff oder der Charakter wird gezwungen, etwas zu tun, wofür er nicht gebaut war, und der „Triumph“ besteht darin, dass er größtenteils heil bleibt."},
 {a:"Beispiel: Moranir hat ein düsenbetriebenes Drachensegel mit der Startart Anlauf. Es ist ein beeindruckendes Stück Ausrüstung, doch er ist nicht in der Lage, es zu würdigen – er wurde durch eine Kollision in der Luft mit einem Pteranha vorübergehend bewusstlos geschlagen. Ohne seine Lenkung treibt das Drachensegel ihn mit unglaublicher Wucht in die Wellen, eine Bruchlandung, die ihm nicht erlaubt, sorgfältig abzubremsen. Das Glühwürmchen verteilt drei Markierungen Stumpf-Schaden, um den Aufprall der ungünstigen Landung darzustellen."},
 {h:"Luftschiffe & Hochhafen-Docks"},
 {a:"Einer der Vorteile eines Hochhafens ist, dass er gezielt für leichte Starts und Landungen entworfen ist. Bei Nutzung eines Hochhafens können Luftschiffe die üblichen Startkosten ihres Auftriebssystems ignorieren und nehmen bei Bruchlandungen keinen zusätzlichen Schaden."},
 {a:"Beispiel: Die Kaboska fährt durch eine zerstörte Siedlung, die an eine Wolke aus Geistern gekettet ist, die Gebäude schwingen wild hin und her. Das mag wie ein schrecklicher Ort zum Landen wirken, doch ein paar geschäftstüchtige Leute haben dort oben einen Hochhafen gebaut – trotz der allgegenwärtigen Gefahr sind Starts und Landungen überraschend leicht, solange Luftschiffe die Landebahnen des Hochhafens nutzen."},
 {bsp:"Flug im Spiel, Alternativ", z:[
  ["Todd","Ich finde, es ist an der Zeit, dass wir dieses Ironshard Sail ausprobieren … Wir haben genug dafür eingetauscht, da können wir es auch benutzen!"],
  ["Laura","Solange du bereit bist, die Steuerung zu übernehmen – diese ganze Sache mit dem Himmelsfahren ist etwas, wovon mein Charakter weit entfernt überzeugt ist. Als Hacker …"],
  ["Glühwürmchen","Keine Sorge, Laura, dort oben gibt es mehr zum Durchsägen, als du denkst! Und Todd, wenn du abheben willst, kannst du das definitiv. Kennst du das Verfahren?"],
  ["Todd","Jep – ich beschleunige, bis wir eine gute Geschwindigkeit haben, und ziehe dann an diesem glänzenden neuen Hebel hier, der die Magnetovoltaik für das Segel einschaltet und uns in die Himmel schiebt. Ich muss dafür nicht würfeln, oder?"],
  ["Inge","Ja, stimmt, es sei denn, das Gelände ist wirklich gegen uns. Die Startkosten musst du aber trotzdem zahlen."],
  ["Glühwürmchen","Also, gute Nachricht und schlechte Nachricht – ihr müsst nicht würfeln, um in die Luft zu kommen, aber sobald ihr es tut, ertönen hinter euch Alarme aus dem Writling-Lager. In dem Moment, in dem ihr ins Sichtfeld geratet, feuert eine ihrer Backbord-Stellungen und schickt einen Hagel Schrapnell Richtung Schiff."],
  ["Todd","Verdammt noch mal! Gut, nun, ich füge für die Startkosten eine Markierung auf dem Neigungs-Wert hinzu, und dann … Nun, haltet euch fest, Leute! Ich nutze denselben Wert, um eine Fassrolle zu machen und zur Seite zu ziehen, tief über den Wellen bleibend, damit sie uns nicht so gut verfolgen können."],
  ["Glühwürmchen","Ein riskanter Zug, aber einer, der klappen könnte. Nimm einen Abzug von eins und würfle!"],
  ["Laura","Im Spiel war das eine schreckliche Idee … Außerhalb des Spiels: Lasst es uns unbedingt tun!"]
 ]}
]});
L.push({id:"sr-blau-lagen", k:K, t:"Wetter- und Umgebungslagen", p:24, q:"sr", b:[
 {a:"Die Himmel sind nicht immer freundlich, und ihre Bewohner sind alles andere als das. Egal wie erfahren ein Aeronaut oder wie fähig ein Schiff ist, die Umgebung ist im Wilden Blau ebenso gefährlich wie auf den Wellen darunter. Die Bedingungen, unter denen du fliegst, helfen zu bestimmen, ob Start, Landung, Manöver oder sogar die grundlegende Fähigkeit zu fliegen einen Wurf irgendeiner Art erfordert. Zum Glück sind diese Regeln nichts, worum du dir als Spieler Sorgen machen müsstest, es sei denn, sie kommen ausdrücklich in einem Aspekt oder Auftriebssystem vor – außerhalb dieser Fälle sind sie allein Sache des Glühwürmchens und helfen ihm zu entscheiden, wann ein Spieler würfeln sollte und wie viel Abzug gelten soll."},
 {h:"Eine Liste von Lagen"},
 {a:"Die Kästen unten beschreiben ein paar häufige Lagen und ob sie sich positiv oder negativ auf das Fliegen auswirken. Das Fliegen mit einer oder mehreren positiven Lagen kann den Abzug für ein schwieriges Manöver senken oder die Notwendigkeit eines Wurfs für ein Manöver ganz beseitigen. Das Fliegen mit einer oder mehreren negativen Lagen erhöht den Abzug, erzwingt Würfe, die sonst nicht nötig wären, oder verringert die Wucht flugbezogener Aktionen. Je nach Besonderheiten von Schiff, Charakter und Lage kann es weitere Nachteile oder Vorteile geben – scheue dich nie zu fragen! Die folgenden Beispiele sind bei Weitem nicht erschöpfend, sollten aber die häufigsten Lagen abdecken, denen Wildsegler und Luftschiffe auf dem Weg ins oder durch das Wilde Blau begegnen."},
 {c:"Günstige Winde (positiv)", x:"Kernpunkte: Es ist ein wundervoller Tag zum Fliegen! Alle Flugstile sind leichter zu bewältigen."},
 {c:"Nebel oder Sporenwolken (negativ)", x:"Kernpunkte: Erschweren es, Starts und Landungen einzuschätzen und Ziele in der Luft auszumachen."},
 {c:"Günstige Thermik (positiv)", x:"Kernpunkte: Abzuheben ist deutlich leichter, wenn der Atem der Wildnisse dich trägt."},
 {c:"Stürme (negativ)", x:"Kernpunkte: Winde rütteln, und Blitze versengen die Luft – eine schreckliche Lage für alle Start- und Flugarten."},
 {c:"Bekannte Magnetfelder (positiv)", x:"Kernpunkte: Metallene Luftschiffe und Aeronauten, die auf Magnetismus oder Mechanismen setzen, haben es leichter."},
 {c:"Unberechenbare Kräfte (negativ)", x:"Kernpunkte: Alles Magnetische, an Luftschiffen wie an Aeronauten, spielt verrückt."},
 {c:"Weiche, üppige Blätter (positiv)", x:"Kernpunkte: Ein Segen für Starts wie Landungen ohne nahen Hochhafen."},
 {c:"Bedrängende Flieger (negativ)", x:"Kernpunkte: Ob in Verfolgung oder im offenen Angriff, Manöver sind bei aktiver Störung schwerer auszuführen."},
 {a:"Beispiel: Die Quotidian Quillfish ist für Luftkampf gebaut, und als sie in der oberen Atmosphäre einen übergroßen Nightbarrel angreift, versucht der Pilot einen Looping, der sie hinter den räuberischen Vogel bringen und der Crew an Deck einen freien Schuss ermöglichen soll. Das ist nicht das einfachste Manöver, und normalerweise würde die Anwesenheit eines nahen Angreifers den Abzug auf dem Wurf erhöhen, doch der Vogel taumelt bereits von einem früheren Schuss. Unter Berücksichtigung der günstigen Winde in der Gegend bittet das Glühwürmchen den Piloten, ohne Abzug zu würfeln; trotz der Gefahr, die das Manöver mit sich bringen könnte, spricht vieles für die Quillfish."},
 {h:"Besondere Lagen"},
 {a:"Die Liste der Optionen links deckt sicher nicht alles ab, was die Himmel einer Crew entgegenwerfen können. Wie in jeder anderen Lage wird vom Glühwürmchen erwartet, dass es die Vor- und Nachteile einer Situation in Bezug auf Gefahr, Schwierigkeit und Dramatik abwägt, wenn es Würfe verlangt."},
 {a:"Beispiel: Die Stinking Remora befördert eine Ladung gekäfigter Raubpflanzen, bereit, weit weg von der Siedlung, die sie belästigt haben, zurück in die Wildnisse entlassen zu werden. Die Pflanzen erzeugen im Rahmen ihres Fressvorgangs ihr eigenes Gas, das leichter als Luft ist, und das Glühwürmchen entscheidet, dass dies das Reisen durch die Luft tatsächlich erleichtert, besonders Starts. Alles in allem hat die Fracht das Schiff ein wenig leichter gemacht."},
 {a:"Bei der Betrachtung einer neuen atmosphärischen oder Umgebungslage sollten sich Glühwürmchen nicht nur darauf konzentrieren, ob sie es für jene in der Luft schwerer oder leichter macht. Das interessante mögliche Zusammenspiel einer Lage mit Schiffskomponenten oder Aspekten ist genauso wichtig."},
 {h:"Beschädigte Auftriebssysteme"},
 {a:"Eine zusätzliche Sorge für Luftschiffe: Hat ein Auftriebssystem strukturellen Schaden genommen, kann es gut als negative Lage zählen – oder schlimmer."},
 {a:"Beispiel: Gourd’s Run nutzt einen Gassack zum Starten und Landen, doch die Harpune eines Räubers hat ihn auf der letzten Reise durchlöchert. Bis er repariert ist, entscheidet das Glühwürmchen, dass alle Landungen außerhalb eines Hochhafens als Bruchlandungen zählen."},
 {a:"Wildsegler erleiden keine Nachteile, wenn der Aspekt, der ihnen eine Startart oder einen Flugstil gibt, markiert ist – manche brauchen sogar eine Markierung, um überhaupt aktiviert zu werden –, aber sie könnten welche haben, wenn sie eine Verletzung haben, die einem glatten Flug im Weg stünde."}
]});
L.push({id:"sr-blau-lagen-persoenlich", k:K, t:"Lagen sind persönlich", p:25, q:"sr", b:[
 {a:"Eine wichtige Erinnerung – während ein furchterregender Sturm für die meisten Aeronauten offensichtlich ein Nachteil ist, würde sich ein fliegender Tempest sofort heimisch fühlen. Wenn das Glühwürmchen entscheidet, wie die Lagen sind und ob sie positiv oder negativ sind, sollte es sowohl mechanische als auch erzählerische Faktoren berücksichtigen."},
 {a:"Beispiel: Brea ist von Beruf Drachensegler, hat aber auch ein paar Aspekte vom Posten Screw. Während sie und ihre Gefährten versuchen, an der Flanke eines eisenreichen Gebirges hinabzugleiten, entscheidet das Glühwürmchen, dass sich die Bedingungen wegen des unberechenbaren Magnetismus der Vorkommen darunter verschlechtern. Und für ihre Gefährten stimmt das auch – doch Brea kann dank eines ihrer Aspekte magnetische Kräfte sehen. Sie erinnert das Glühwürmchen daran, und es kehrt die Entscheidung in Bezug auf sie um und befindet, dass ihre Gefährten zwar etwas mehr Mühe haben könnten, sie selbst aber völlig unberührt ist."},
 {bsp:"Lagen im Spiel", z:[
  ["Laura","Es sieht rau da draußen aus …"],
  ["Glühwürmchen","Da hast du recht. Regen peitscht gegen das Fenster, und in der Ferne knistert Blitz. Ihr fahrt tiefer in den Sturm."],
  ["Kyllian","Lass mich raten – das Schiff wird das nicht sehr mögen?"],
  ["Glühwürmchen","Wieder richtig. Neben der verringerten Sicht fügt der Sturm jedem Manöver, das ihr macht, einen Abzug hinzu, solange er in voller Stärke tobt. Ihr werdet wohl vorerst keinen Blitzen ausweichen."],
  ["Inge","Moment – ich glaube, das müssen wir gar nicht!"],
  ["Todd","Was, wir lassen uns einfach treffen? Ich weiß, ich bin sonst der Volldampf-Typ, aber …"],
  ["Inge","Nein, ich meine, der Sturm ist trotzdem ein Problem. Aber dieser Blitz speziell? Wir haben einen Blitzableiter! Wir haben ihn schon eine Weile nicht benutzt, weil wir unter dem Gestrüpp waren, aber hier oben wird er brillant funktionieren, um uns zu schützen!"],
  ["Glühwürmchen","Weißt du was? Du hast völlig recht! Mit diesem Stab lassen Blitzeinschläge das Schiff nicht nur unversehrt – sie laden sogar eure Keramikbatterien auf. Solange ihr im Sturm seid und die Motoren so viel zusätzlichen Saft bekommen, halte ich es für fair zu sagen, dass ihr Vorwärtspreschen könnt, selbst mit den Auftriebssystemen, die ihr gerade installiert habt."],
  ["Todd","Wieder mit Tempo reisen? Da bin ich dabei. Gut gesehen, Inge! Nun, ich glaube, ich bin mit dem Steuer dran …"]
 ]}
]});
L.push({id:"sr-blau-reisen", k:K, t:"Reisen durch das Wilde Blau", p:26, q:"sr", b:[
 {erz:"Grimnebulin war einmal über die Reling gegangen; es war keine Erfahrung, die er eilig wiederholen wollte.\nEs war ein Plünderer-Angriff gewesen, Piraten in Falkenfedern und gestohlenen Knochen, die von den Ästen eines Tallshanks herabsprangen, unter dem sie hindurchfuhren. Mehr als einer von ihnen hatte bei ihrem ersten Angriff das Deck des Schiffs verfehlt, doch er hatte keine Schreie gehört – ein Blick über den Rand zeigte Gestalten, die davonglitten, die Arme weit gespreizt und Streifen von Leinwand, die im Wind wehten.\nAber als einer von ihnen ihn einige Augenblicke später hinabgestoßen hatte, hatte er keine solchen Vorbereitungen gehabt.\nGrimnebulin hatte den größten Teil seines Lebens mit den Wellen kaum einen Steinwurf entfernt verbracht, sein Wechsel vom erfahrenen Wildsegler zum zufälligen Aeronauten die Folge einer Laune des Kapitäns.\nUnd selbst nach seinen Jahren auf den Wellen, und vielen weiteren im Blau, war dieser Sturz das Nächste an der Ewigkeit gewesen, was er je erlebt hatte."},
 {a:"Eine weit jüngere Mode als der persönliche Flug, und eine, die von einer Crew erhebliche Investitionen verlangt, um sich auszuzahlen. Der Vorgang, einen bestehenden Wellenschneider in ein Luftschiff umzubauen, mag so einfach aussehen, wie einen Gassack obendrauf zu setzen, aber es steckt (hoffentlich) weit mehr Arbeit dahinter."},
 {a:"Alle Luftschiffe verlassen sich auf Auftriebssysteme, um in der Luft zu bleiben, und jedes davon erlaubt einem Schiff, nach der Installation eine bestimmte Start- oder Flugart zu nutzen (eine Liste der Auftriebssysteme findest du auf S. 112)."},
 {h:"Reisen in schwindelnder Höhe"},
 {a:"Obwohl weit von der Wildheit der Wellen entfernt, bleiben die Grundregeln für eine Reise in der Höhe dieselben – du wählst einen Kurs, brichst (hoffentlich) in die richtige Richtung auf, markierst ein paar Leisten und machst ein paar Wachwürfe und landest irgendwo anders als dort, wo du begonnen hast. So einfach ist das!"},
 {a:"… Zumindest meistens. Die nächsten Seiten behandeln, wie sich das Reisen per Luftschiff vom Durchschneiden der Wellen unterscheidet, und geben neue Optionen, die besonders Crews gefallen werden, die ihr Herz daran gehängt haben, das Wilde Blau zu erkunden."},
 {a:"Diese zusätzlichen Optionen sind nicht der einzige neue Regelsatz für Luftreisen. Luftschiffe ziehen auf ihrer Reise Aufmerksamkeit auf sich, meist negative oder potenziell gefährliche. Diese Facette des Lufttransports, Aufmerksamkeit, wird im letzten Abschnitt dieses Kapitels gesondert behandelt. Auf S. 32 findest du eine detaillierte Übersicht über das System und die Gefahren, die es mit sich bringt – bis dahin musst du nur wissen, dass das Schweben durch die Himmel nicht annähernd so leicht oder entspannend ist, wie die Vögel es erscheinen lassen."},
 {h:"Überblick über Zusatzregeln"},
 {a:"Zu jeder dieser Regeln gibt es auf den nächsten Seiten mehr Einzelheiten, aber als Kurzreferenz deckt dieser Abschnitt ab …"},
 {l:["Treiben: Für Schiffe, die in der Luft Anker werfen können, ohne zu landen, eine Gelegenheit, langsam zu treiben, während die Crew ruht, und dabei möglicherweise die Zahl der Markierungen auf der Reiseleiste zu erhöhen (oder zu verringern).","Wache-Ergebnisse: Ein neuer Satz Ergebnisse für Segler, die während einer Luftreise Wache gehen, unter Berücksichtigung ihres erweiterten Sichtfelds und der anderen möglichen Begegnungen.","Höhe: Ein System rund um die Wolkenschicht, das den Himmel in Schichten teilt, ähnlich wie die Schichten der See unten. Höhe spielt erst eine Rolle, sobald Schiffe durch die Wolkenschicht reisen.","Ärger suchen: Ein neues System für jene, die Problem um Problem wollen, das Crews erlaubt, während einer Reise Sichtungen zu sammeln und zu einer stets gefährlichen, aber einträglichen Begegnung zu verknüpfen."]},
 {box:"Werte im Flug", x:["Jeder Wert eines Schiffs ist auch im Flug noch nützlich, obwohl sich die Umstände, unter denen er gewürfelt wird, ändern können.","· Panzerung: Funktioniert genau wie auf den Wellen und schützt ein Schiff vor Schaden.","· Dichtung: Dichtungen halten die Umgebung innerhalb eines Fahrzeugs sicher für die Aeronauten, die darauf angewiesen sind.","· Tempo: Ein weiterer einfacher, meist genutzt, um Änderungen an der Fluggeschwindigkeit eines fliegenden Fahrzeugs vorzunehmen (oder um einem Schiff, das aufs Gleiten setzt, einen sicheren Start zu erlauben).","· Sägen: Weiterhin genutzt, um Hindernisse zu durchschneiden (wobei das in der Luft weit schwieriger ist), kann aber auch genutzt werden, um zu verhindern, dass Nebel und Wolkenbänke die Sicht eines Piloten verdecken, indem die Luft vor dem Schiff aufgewirbelt wird.","· Tarnung: Hilft einem Schiff, unbemerkt zu bleiben, entweder durch Dämpfen von Motorgeräuschen oder durch Verstecken in schwebenden Hindernissen oder Sonnenblendung.","· Neigung: Der König der Luftwerte, gewürfelt für glattere Starts, Landungen und knifflige Manöver."]}
]});
L.push({id:"sr-blau-treiben", k:K, t:"Treiben", p:27, q:"sr", b:[
 {a:"Für manche Luftschiffe ist Bewegung eine Notwendigkeit; jene, die sich auf Motorschub und Aerodynamik verlassen, um in der Luft zu bleiben, finden es schwierig oder gar unmöglich, zu „stoppen“, ohne vom Himmel zu stürzen. Das macht das Ankerwerfen, normalerweise eines der einfacheren Elemente einer Reise, in der Luft zu einer kniffligeren Angelegenheit. Zwar ist es möglich, dass ein Schiff im Wilden Blau an schwebenden Trümmern oder einer stabilen Luftpflanze vertäut wird, doch der sicherste Weg für solche Fahrzeuge ist, zu den Wellen abzusteigen und wie gewohnt den Anker zu werfen. Das ist ein guter Vorwand für Chars und Surgeons, Ressourcen von den Wellenspitzen zu sammeln, die Unterbesatzung wird die Pause wahrscheinlich zu schätzen wissen, und vor allem besteht keine Gefahr, aus dem Himmel zu fallen, wenn etwas schiefgeht."},
 {h:"Rast im Blau"},
 {a:"Hat ein Schiff jedoch den Flugstil Schweben oder irgendeine Art Luftankersystem (wie jene auf S. 119), hat die Crew ein paar mehr Optionen zur Verfügung. Die erste ist, in der Luft Anker zu werfen, in der Luft zu hängen und kleine Korrekturen vorzunehmen, um an einem Ort zu bleiben. Das ist vielleicht nicht ganz so erholsam wie ein voller Halt auf den Wellen darunter, aber es erfüllt seinen Zweck."},
 {a:"Die zweite ist zu treiben, in der Luft zu bleiben (und vielleicht die Motoren herunterzufahren, wenn das Schiff mit einem Auftriebssystem leichter als Luft läuft) und sich von den Winden dorthin tragen zu lassen, wohin sie wehen. Das gibt der Crew eine Gelegenheit zu rasten, zu arbeiten oder zu schlafen und bringt sie vielleicht sogar näher ans Ziel."},
 {h:"Regeln fürs Treiben"},
 {a:"Das wird in allem wie Ankerwerfen behandelt, bis auf einen Unterschied – das Glühwürmchen macht hinter den Kulissen einen zusätzlichen 1W6-Wurf. Bei einer 6 treibt das Schiff in eine Richtung, die der Crew tatsächlich hilft, und fügt der Reiseleiste eine Markierung hinzu. Bei einer 5 oder 4 bleibt das Schiff im Wesentlichen, wo es ist – es macht keinen Fortschritt, verliert aber auch keinen, es hängt für die Dauer der Szene am Himmel. Bei einer 3, 2 oder 1 treibt das Schiff weit vom Kurs ab und leert eine Markierung auf der Reiseleiste."},
 {a:"Dieser Wurf kann durch die Art des Wetters beeinflusst werden, dem das Luftschiff ausgesetzt ist – ein Sturm oder starke Winde könnten das Glühwürmchen entscheiden lassen, stattdessen 2W6 zu würfeln und das niedrigere Ergebnis zu nehmen."}
]});
L.push({id:"sr-blau-wache", k:K, t:"Wache-Ergebnisse", p:28, q:"sr", b:[
 {a:"Obwohl die Mechanik des Wachegehens in der Luft mit der auf Wellenhöhe identisch ist, können sich die Ergebnisse, die du erhältst, ein wenig unterscheiden. Wenn ein Spieler von einem Luftschiff aus einen Wachwurf macht, kann sich das Glühwürmchen entscheiden, die Ergebnistabelle rechts statt der üblichen Wellenschneider-Tabelle im Grundregelwerk zu nutzen."},
 {box:"Überfüllte Himmel", x:["Eines, das ihr als Gruppe bei eurem Spiel entscheiden müsst, ist, ob die Himmel eurer persönlichen Wildsee überfüllt sind, zumindest verglichen mit den Himmeln unserer eigenen Welt. Wie häufig sind schwebende Inseln und andere Luftschiffe, Räuber der Lüfte und treibende Himmelspflanzen? Wenn ihr die Himmel spärlich halten wollt, ist ein einfacher Weg, die Menge an Reise zu erhöhen, die ein einzelner Wachwurf abdeckt. Das ist eine rein erzählerische Änderung, da es von vornherein (absichtlich) keine festen Dauern für solche Würfe gibt. Es bedeutet nur, dass, wenn eure Spieler darauf aus sind, viele himmelsbasierte Dinge zu begegnen, zwischen den eigentlichen Sichtungen durchaus Tage liegen können statt Stunden oder Minuten."]},
 {h:"Wachwurf-Ergebnisse für das Wilde Blau"},
 {a:"Frieden (6): Es gibt einen Grund, warum man es das Wilde Blau nennt – es mag weit sein, vielleicht sogar noch unerforschter, aber selten ist es friedlicher. Du erlebst vielleicht …"},
 {tab:{k:["Ergebnis","Was du erleben könntest"],z:[
  ["6 · Frieden","Einen wirklich klaren Tag, der der Crew Zeit für eine Montage gibt. Nützlich zum Heilen und Reparieren."],
  ["6 · Frieden","Eine Sichtung einer fernen Bedrohung oder Gelegenheit, zu weit entfernt, um ein unmittelbares Anliegen zu sein."],
  ["6 · Frieden","Momente müßigen Klatsches, der Gerüchte zu Flüstern und Geschichten zu Ergänzungen bestehender Seekarten spinnt."],
  ["6 · Frieden","Die Rhythmen mögen neu und ungewohnt sein, aber die Unterbesatzung, die ein Himmels-Shanty singt, hält die Stimmung oben."],
  ["6 · Frieden","Einen unerwarteten Durchbruch beim Starren in die Himmel, der mehrere Kästchen auf einem Projekt markiert."],
  ["6 · Frieden","Die Unterbesatzung, die sich über irgendeine Kleinigkeit zankt, genug für derbe Worte, aber nicht für fliegende Fäuste."],
  ["Ordnung (4–5)","Intakte Strukturen sind in den Himmeln ungewöhnlich, doch Fragmente und Absonderlichkeiten gibt es reichlich. Du erlebst vielleicht …"],
  ["Ordnung (4–5)","Ein Signal von einem fernen Luftschiff, das Kontakt aufzunehmen versucht."],
  ["Ordnung (4–5)","Das Glitzern einer Satellitenstadt, weit über den Wolken."],
  ["Ordnung (4–5)","Einen Hochhafen, gespickt mit Andockbuchten, Landebahnen und Landestreben, der perfekte Ort zum Rasten."],
  ["Ordnung (4–5)","Eine schwebende Ruine, in der Luft gehalten von ungewöhnlichem Pflanzenleben, uralten Motoren oder komplexem magnetischem Zusammenspiel."],
  ["Ordnung (4–5)","Einen einsamen Aeronauten, einen Drachensegler oder Ballonfahrer, von den Winden erfasst und vom Kurs geworfen."],
  ["Ordnung (4–5)","Ein Luftschiffwrack, leer von Leben und noch immer wie ein kunstvolles Grabmal durch die Himmel treibend."],
  ["Natur (1–3)","Crews sind in der Höhe ebenso von der Natur umgeben wie in den Tiefen, nur weiter auseinander und weniger geneigt, das Schiff beim Fahren zu verheddern. Du erlebst vielleicht …"],
  ["Natur (1–3)","Die Aufmerksamkeit, die das Schiff auf sich zieht, erhöht die Aufmerksamkeit und markiert unerwartet ein Wachsames Auge."],
  ["Natur (1–3)","Eine Berggipfel-Insel oder ein anderes geografisches Merkmal, das hoch genug reicht, um ihm ausweichen zu müssen."],
  ["Natur (1–3)","Ein Wunder der Himmel, etwas, das man besingen oder mit Eifer festhalten kann. Heilt Morast."],
  ["Natur (1–3)","Einen Schrecken des Wilden Blaus, der die Crew vielleicht zwingt, sich der Leere – oder dem Leben – des Himmels zu stellen. Markiert Morast."],
  ["Natur (1–3)","Eine Begegnung mit einer der Kreaturen der oberen Luft."],
  ["Natur (1–3)","Der Anblick von etwas Leviathan-Artigem, das auf das Schiff zuhält."]
 ]}}
]});
L.push({id:"sr-blau-hoehe", k:K, t:"Höhe", p:29, q:"sr", b:[
 {a:"Die Wildsee verfolgt die Höhe eines Schiffs nicht in Zahlen, aber es gibt drei „Schichten“, die für Crews nützlich sein könnten, die viel Zeit in der Luft verbringen wollen. Sie unterteilen den Himmel ähnlich wie die Schichten der See, mit zugehörigen Regeln für größere Höhen, die dem Geschehen eine Prise Gefahr hinzufügen. Die drei angebotenen Höhenschichten sind …"},
 {l:["Unter den Wolken","In den Wolken","Über den Wolken"]},
 {h:"Die Höhe wählen"},
 {a:"Jedes Mal, wenn der Charakter am Steuer die Geschwindigkeit eines Luftschiffs auf einer Reise wählt oder ein Manöver ausführt, kann er auch die Höhe wählen, in der es reist. Luftschiffe, die von den Wellen starten, gelangen natürlich in den Bereich unter den Wolken, während der Start von einem Hochhafen einem Schiff erlauben kann, sofort in den Bereich in oder über den Wolken zu gelangen. Sofern nichts anderes angegeben ist, wird angenommen, dass Luftschiffe unter den Wolken reisen. Andere Höhen kommen nur ins Spiel, wenn die Crew oder das Glühwürmchen sie wählt."},
 {h:"Die Schichten des Himmels"},
 {a:"Die Höhe, in der ein Schiff reist, bestimmt, ob besondere Regeln gelten. Der Rest der Seite behandelt, was jede Höhe erzählerisch und mechanisch bedeutet."},
 {c:"Unter den Wolken", x:"Das Fliegen unter den Wolken hält dich nah an den rauschenden Wellen (was, gemessen an der Höhe des Kronendachs der Wildsee, in realweltlichen Begriffen immer noch ziemlich hoch ist). Es kann ein Schiff beschreiben, das knapp über den Ästen dahingleitet oder sie mit leichten hundert Fuß Abstand überfliegt – genaue Maße sind weniger wichtig als erzählerische Wirkung und allgemeines Gefühl.\nMechanisch gibt es keine besonderen Regeln für das Reisen unter den Wolken – es ist nicht umsonst die Voreinstellung."},
 {c:"In den Wolken", x:"Die Domäne von Stürmen und unruhiger Luft; die Höhen, die man erklimmen muss, um diese Art Höhe zu erreichen, sind schwindelerregend. Kreaturen und Siedlungen sind selten, doch jene, die es schaffen, sich auf dieser Ebene eine Nische zu schnitzen, sind oft faszinierende Sorten.\nMechanisch ist das Fliegen in den Wolken ein hervorragender Weg, außer Sicht zu bleiben, verdeckt aber zugleich die eigene Sicht der Crew. Murksicht und andere unheimliche Sinne machen das Navigieren in dieser Himmelsschicht etwas leichter.",
  l:["Abzug bei Würfen, die auf Sicht oder Aufmerksamkeit beruhen, es sei denn, ein Charakter hat einen Aspekt, der es ihm erlaubt, durch dichte Wolken zu sehen.","Das Auftreffen auf Hindernisse beim Vorwärtspreschen führt fast sicher zu einem üblen Absturz und fügt zu jedem anderen Effekt des Hindernisses dieselben Bruchlandungs-Regeln von S. 23 hinzu (selbst wenn das Schiff technisch nicht abstürzt oder landet, werden die Ausweichmanöver, die nötig sind, um einer plötzlich auftauchenden Bedrohung zu entgehen, für Schiff und Crew belastend sein).","Erhöhe die Wucht bei Würfen, um sich vor allem außerhalb der unmittelbaren Umgebung des Schiffs zu verstecken."]},
 {c:"Über den Wolken", x:"Eine frostige Leere, die dem Weltraum eindeutig zu nahe ist; die Himmel über den Wolken sind fast völlig frei von traditionellem Leben. Forscher in diesem feindlichen Reich finden vielleicht bewachte Satellitenstädte (S. 14) oder werden sogar von hyperangepassten Räubern verfolgt, doch die größte Bedrohung in solcher Höhe sind die Himmel selbst.\nMechanisch bedeutet das Fliegen über den Wolken, dass ein Schiff in der größten Höhe reist, in der es noch bequem kreuzen kann, wo die Luft dünner wird und der Wind eisige Zähne bekommt.",
  l:["Abzug bei Würfen, um sich zu verstecken oder der Aufmerksamkeit anderer Fahrzeuge oder Kreaturen zu entgehen, die über den Wolken reisen, aber erhöhte Wucht bei Versuchen, sich vor allem darunter zu verstecken.","Crew, die längere Zeit an Deck ist, beginnt ohne Frost-Resistenz oder Kleidung für warmes Wetter zu leiden und erleidet Verletzungen durch extreme Kälte und Windchill. In der Nähe von Wärmequellen zu bleiben oder unter Deck zu gehen, kann das vermeiden."]},
 {h:"Atmosphärische Veränderungen"},
 {a:"Die Wolkenschicht des Wilden Blaus mag ein nützlicher Bezugspunkt für die Höhe sein, aber das heißt nicht, dass sie immer da ist oder immer genau so auftritt, wie die Regeln auf dieser Seite sie beschreiben. Wenn du von der „typischen Flugerfahrung“ abweichen willst, kannst du sie mit den Optionen unten würzen – oder sie als Lagen nutzen! Keiner dieser alternativen Effekte hält wahrscheinlich eine ganze Reise lang an, und sie können von einem Charakter vorhergesagt werden, der das Wetter beobachtet oder in den Künsten der Himmelsfahrt bewandert ist."},
 {c:"Wolkenloser Himmel", x:"Die Wildsee hat von Zeit zu Zeit wolkenlose Tage, je nach Region, Jahreszeit und atmosphärischen Effekten (und erzählerischer Angemessenheit, natürlich). Auch wenn ein Schiff weiterhin über oder unter der Stelle reisen kann, wo die fehlenden Wolken üblicherweise wären, nimmt es Abzug, wenn es versucht, sich zu verstecken oder der Aufmerksamkeit von Individuen zu entgehen, die es sehen könnten – wo auch immer es fliegt, ist es ungeschützt."},
 {c:"Gewitterwolken", x:"Ein von Stürmen geplagter Himmel ist kaum der sicherste Ort zum Fliegen. Das Reisen über den Wolken wird für die meisten eine einigermaßen normale Erfahrung sein, doch wenn ein Schiff versucht, eine Route in oder unter ihnen zu nehmen, ist es dem Risiko massiven Strom-Schadens durch Blitzeinschläge ausgesetzt."},
 {c:"Wilde Winde", x:"Im Wesentlichen das Gegenteil von Gewitterwolken, spuken solche Winde in der oberen Atmosphäre und haben selten großen Einfluss auf die unteren Himmel nahe dem Gestrüpp. Das Reisen unter der Wolkenschicht wird wie üblich behandelt, doch höher zu fliegen riskiert massiven Stumpf-Schaden am Schiff, wenn es von einer besonders starken Böe erwischt wird."},
 {c:"Jetstreams", x:"Obwohl meist unkartiert, können Jetstreams die Dauer einer Reise dramatisch verkürzen, wenn ein fähiger Pilot sie nutzt. Reist man in einem Jetstream, entscheidet der Charakter am Steuer nicht über die Höhe, in der das Schiff fliegt (das Glühwürmchen bestimmt sie stattdessen, da das Schiff in der Strömung bleibt). Er macht jedoch jedes Mal, wenn er Fortschritt macht, eine zusätzliche Markierung auf der Reiseleiste."}
]});
L.push({id:"sr-blau-aerger-suchen", k:K, t:"Ärger suchen", p:30, q:"sr", b:[
 {erz:"„Fragst du dich je, wo all die Vögel hin sind?“\nDie Ingenieurin sah von den aufgeklappten Innereien des Schiffs auf und wischte sich fettige Locken aus der Stirn. Ihr Assistent stellte von Zeit zu Zeit ziemlich seltsame Fragen, aber meist ging es um Treibstoffverhältnisse und Wechsel oder zumindest etwas vage Mechanisches.\n„Wo sie hin sind? Die sind in den Wellen, Junge, nisten in Ästen und flattern überall herum. Haufenweise dort unten.“\n„Ja, aber … Warum haben sie Angst vor den Himmeln?“"},
 {h:"Ärger suchen (neue optionale Station)"},
 {a:"Eine neue Station, die genutzt werden kann, während ein Luftschiff vorankommt (ähnlich wie Den Motor warten und Kartografieren aus dem Grundregelwerk). Ärger suchen erlaubt der Crew, auf einer Luftreise die Höhe zu nutzen, in der sie reist, um bestimmte Bedrohungen von großer Bedeutung zu erspähen … Doch die Belohnungen kommen nicht ohne Preis."},
 {h:"Die Ärger-Leiste"},
 {a:"Die Ärger-Leiste ist dazu gedacht, auf Luftreisen gefüllt zu werden, und ist eine senkrechte Leiste mit drei Kästchen, die du im Notizbereich des Schiffs- oder Charakterbogens eintragen kannst."},
 {h:"Die Ärger-Leiste markieren"},
 {a:"Jedes Mal, wenn das Schiff auf einer Reise Fortschritt macht (ob durch Pfad schneiden oder Vorwärtspreschen), kann ein Crewmitglied, das weder auf Wache noch am Steuer ist, Ärger suchen. Wenn ein Wildsegler Ärger sucht, markiert er ein Kästchen auf der Ärger-Leiste und schreibt neben das gefüllte Kästchen eine kurze Beschreibung dessen, was er gesehen hat."},
 {a:"Beispiel: Grendyl sucht Ärger, während sein Schiff über die Baumwipfel schwingt. Sein Spieler markiert eines der Kästchen auf der Ärger-Leiste und schreibt „Vögel mit Rauchfahne“ daneben. Ein Omen, eine Bedrohung? Er wird es nicht herausfinden, bis das letzte Kästchen markiert ist, aber es sieht nicht gut aus."},
 {a:"Die gesehenen Dinge können positiv, negativ oder vage dazwischen sein, aber eines können sie nicht sein: untersucht werden – sie müssen flüchtig sein, Sichtungen einer potenziell größeren Bedrohung oder Belohnung."},
 {h:"Wenn die Ärger-Leiste voll ist"},
 {a:"Sind alle drei Kästchen markiert, kann die Crew gemeinsam entscheiden, welchen Ärger sie findet. Dazu kombiniert sie zwei der drei kleinen Phrasen und nutzt sie als Beschreibung eines Ereignisses oder Orts, den sie überfliegt (oder unterfliegt, wenn er in den Wolken liegt). Die flüchtigen Blicke fügen sich zusammen, und die Wahrheit wird enthüllt … Und diese Wahrheit ist stets etwas Schlechtes. Es heißt ja nicht umsonst „Ärger suchen“."},
 {a:"Beispiel: Grendyls Crew hat auf ihrer Reise Anzeichen von Ärger erspäht. Sie haben „Vögel mit Rauchfahne“, „Einen Sturm am Horizont“ und „Trümmer, rasch verschlungen“ gesehen. Gemeinsam beschließen sie, dass die erste und die letzte dieser Sichtungen zusammen eine Manufaktur auf einer Felsspitze enthüllen, umkreist von kreischenden mechanischen Vögeln, die ins Gestrüpp hinein- und wieder hinausstoßen."},
 {a:"Sobald das Ereignis oder der Ort geschaffen ist, leere jede Markierung auf der Leiste und lösche die daneben notierten flüchtigen Eindrücke."},
 {h:"Die letzte Phrase"},
 {a:"Die kleine Phrase, die nicht zur Schaffung der Ärger-Begegnung genutzt wird, wird in ein Flüstern umgewandelt und dem Charakter gegeben, dessen Spieler sie geschaffen hat. Das Flüstern muss nicht genau die aufgeschriebene Phrase sein, sollte ihr aber eng verwandt sein."},
 {a:"Beispiel: Grendyls Crew hat zwei der drei Phrasen genutzt, um Ärger zu finden. Die übrig gebliebene Phrase, „Ein Sturm am Horizont“, wird zu einem Flüstern für ihren Char, den Charakter, dessen Spieler diese besondere Phrase geschaffen hat. Weil es für ein Flüstern etwas wortreich ist, kürzt das Glühwürmchen es zu „Ein nahender Sturm“ und der Spieler des Chars notiert es als Ressource auf seinem Charakterbogen."}
]});
L.push({id:"sr-blau-aerger-folgen", k:K, t:"Folgen & Zusatzregeln", p:31, q:"sr", b:[
 {h:"Eine Pause für das Glühwürmchen"},
 {a:"Ärger suchen ist eine rein spielerseitige Mechanik, das Glühwürmchen hat also keinen Einfluss auf die Art des Ereignisses oder Orts, den sich die Crew ausdenkt. Es wird dennoch Elemente davon beschreiben und alle auftretenden Gefahren steuern – es ist schließlich das Glühwürmchen –, doch der eigentliche Schöpfungsteil liegt standardmäßig ganz bei den anderen Spielern."},
 {h:"Grenzen des Ärgers"},
 {a:"Solange die Spieler etwas erschaffen, das die Anzeichen erklärt, die sie gesehen haben, haben sie gute Arbeit geleistet. Aber wie interagieren sie damit? Orte, die durch Ärger suchen geschaffen wurden, müssen nicht sofort untersucht werden. Sie könnten auf einer Art Seekarte vermerkt und später aufgesucht oder sogar als wertvolle Information genutzt werden, um sie Piraten oder Plünderern anzubieten. Sich auf eine durch Ärger suchen erzeugte Begegnung einzulassen, ist immer optional."},
 {h:"Die Kehrseite des Ärgersuchens"},
 {a:"Es steht im Namen! Durch Ärger suchen erzeugte Begegnungen stellen von Natur aus immer eine Gefahr dar, der man sich stellen muss, oder eine Herausforderung, die es zu überwinden gilt."},
 {h:"Der Vorteil des Ärgersuchens"},
 {a:"Der Vorteil ist, dass was auch immer die Crew für ein Ereignis oder einen Ort entdeckt hat, ihr immer etwas Wertvolles als Lohn für das Hineinstürzen in die Gefahr bieten kann. Die genaue Art der Belohnung liegt beim Glühwürmchen, doch positiv getaggte Fracht, zusätzliche Meilensteine, Überlebende, die als Passagiere oder Unterbesatzung mitkommen wollen, oder handlungsentscheidende Informationen sind alle gute Optionen."},
 {box:"Optionale Extras", x:["Eine Garnitur möglicher Ergänzungen; du musst diese Regeln nur nutzen, wenn sie zum bevorzugten Spielstil deines Tischs passen. Besprecht es als Gruppe, bevor ihr sie nutzt …","Flugpläne\nSeekarten zum Folgen zu haben ist ein echter Segen, besonders auf längeren Reisen – es ist leicht, mit der Zeit vom Kurs abzukommen, besonders wenn man sich durch wechselndes oder unbekanntes Gebiet bewegt. Eine passende Seekarte zu besitzen, fügt Wachwürfen einen zusätzlichen W6 hinzu, wobei der Beobachter wählt, welches der gewürfelten Ergebnisse er bevorzugt.","Nachtflug\nReisen bei Nacht durch die Himmel ist ebenso gefährlich wie unten, und keine Menge Bullaugen-Läden und Motordämpfung kann die Anwesenheit eines Luftschiffs ewig verbergen. Wenn du nachts einen Wachwurf machst, würfelt das Glühwürmchen für die Bedrohung möglicher Begegnungen standardmäßig mit 2W6 statt dem üblichen 1W6 und nimmt das niedrigste Ergebnis – das gefährlichere.","Fern der Wellen\nFlüstern und Seekarten sind unterwegs leicht zu ergattern und aufzuzeichnen, Bergegut und Proben jedoch eine andere Geschichte. Wenn du Bergegut oder Proben aus Unterbesatzungs-Wahlen erhalten würdest, die auf Nähe zu den Wellen angewiesen sind, füge dem Erworbenen einen negativen Tag hinzu.","Bedrohungen in der Ferne\nDas erhöhte Sichtfeld gibt der Crew weit mehr Zeit, auf Gefahren und Hindernisse zu reagieren, die auf Wache gesichtet werden. Beim Pfad schneiden erhält der erste Wertewurf, der gemacht wird, um mit einer neuen Bedrohung umzugehen, einen zusätzlichen 1W6 Vorteil."]},
 {bsp:"Ärger suchen im Spiel", z:[
  ["Glühwürmchen","Also eine 6 ist Frieden, was nach der Reise, die ihr hattet, wahrscheinlich eine nette Pause ist. Ich lasse das gern als Montage auf dem Schiff laufen, wenn es Dinge gibt, die ihr erledigen wollt …"],
  ["Todd","Oh, nein nein nein! Ich habe gerade das letzte Kästchen unserer Ärger-Leiste markiert, und ich bin scharf auf einen Kampf."],
  ["Laura","Du bist immer scharf auf einen Kampf!"],
  ["Todd","Das stimmt nicht! Es ist nur … meistens?"],
  ["Glühwürmchen","Nun, Todds Neigungen zu Gewalt und Schurkerei beiseite gelassen, was habt ihr gesehen, als ihr Ärger gesucht habt?"],
  ["Kyllian","Ich nehme „Einen Geysir aus flüssigem Crezzerin“, der aus der Seite eines gebrochenen Baumstamms auf Gestrüpp-Höhe spritzt."],
  ["Kyllian","Oh, wir könnten das mit der „Herde fliehender Füchse“ kombinieren, vielleicht? Irgendeine kleine ökologische Katastrophe, mit der man sich befassen muss?"],
  ["Inge","Oder mit der „Verlassenen Bohrausrüstung“. Vielleicht haben sie einen Baum nach etwas ausgebeutet und eine Ader flüssigen Crezz getroffen?"],
  ["Todd","Die zweite gefällt mir wirklich, vielleicht gibt es da unten einen leeren Arbeitsplatz, bei dem wir vorbeischauen und schweres Gerät klauen könnten."],
  ["Kyllian","Das wäre eigentlich ziemlich nützlich. Also, wenn wir das so machen, bekomme ich die Füchse-Phrase als Flüstern?"],
  ["Glühwürmchen","Genau. Laura, bist du einverstanden?"],
  ["Laura","Wenn wir danach diese Frieden-Montage machen können, ja, ich glaube, das passt für mich. Ich lehne mehr Rohmaterial zum Werkzeugbauen nie ab."],
  ["Glühwürmchen","Großartig! In dem Fall, Kyllian, kannst du dein Ärger-Ergebnis als Flüstern eintragen, und Todd, beschreib mir, wie dieser Arbeitsplatz aussieht, während ihr näher herankommt …"]
 ]}
]});
L.push({id:"sr-blau-aufmerksamkeit", k:K, t:"Aufmerksamkeit", p:32, q:"sr", b:[
 {erz:"Zusammengekauert in ihrer Kabine, die Vorhänge über dem Bernsteinglas-Bullauge zugezogen, kippte Klyka einen weiteren Schluck Spikewein hinunter und griff zitternd nach dem nächsten Buch. Sie hätte nie gedacht, dass sie die rauschenden Wellen vermissen würde.\n„Es ist nur ein weiteres Meer“, hatte sie ihrem Mann gesagt, als sie sich für die Dry & Dapper verpflichtete. Er hatte vorsichtig genickt, aber er war ein altmodischer Ridgeback – sie bezweifelte, dass seine Füße je das Deck eines Wellenschneiders berührt hatten, geschweige denn das eines Luftschiffs. Natürlich hatte er Vorbehalte. Es war einer der Gründe, warum sie ihn liebte, dass er sich genug sorgte, um sich zu ängstigen, selbst wenn er wusste, dass sie den gefährlichsten Routen fernblieb.\nEin Blitzschlag draußen. Die Mottenlaterne flackerte, und Tiefsauer verschwamm auf der Seite vor ihr.\nUnd sie hatte recht gehabt. Es war nur ein weiteres Meer, das Wilde Blau. Ebenso unberechenbar, ebenso voller Leben.\nVielleicht war das das Problem."},
 {a:"Für Segler, die ihr ganzes Leben von der Enge aus Ast, Blatt und Blüte umgeben waren, die die rauschenden Wellen ausmacht, kann die Weite des Wilden Blaus ein Schock für das System sein. So viel Freiheit in der Richtung, in der Höhe, in dem, wann man sich bewegt und wann man treibt … Was könnte das Wilde Blau anderes sein als ein Paradies? Doch erfahrene Aeronauten wissen es besser. Denn mit dieser Freiheit, dieser offenen Weite, kommt die Unfähigkeit, die eigene Anwesenheit zu verbergen – die Ausgesetztheit, ein einzelner Punkt in einem Meer aus Blau zu sein, oder ein bewegtes Licht vor den Sternen. Du kannst von dort oben alles sehen, und alles andere kann dich sehen."},
 {a:"Hier kommt Aufmerksamkeit ins Spiel, eine Mechanik, die die Gefahr darstellen soll, ein einsamer Punkt aus Leben und Interesse zu sein, während man die weiten Himmel bereist. Aufmerksamkeit stellt dar, dass die Welt der Wildnisse Notiz nimmt, welche Aufmerksamkeit das nach sich ziehen kann und die psychische Wirkung des Wissens, dass man umso ausgesetzter ist, je länger man fliegt."},
 {h:"Beobachter"},
 {a:"Beobachter sind legendäre Bedrohungen, von denen Aeronauten flüstern, wenn sie ein paar Getränke zu viel hatten, Kreaturen, die die Grenzen zwischen Mythos und Leviathan verwischen. Sie sind real, diese Beobachter, benannt und gesehen, aber sie könnten unmöglich so mächtig sein, wie die Geschichten behaupten. Zumindest hofft man das."},
 {a:"Beobachter teilen sich in zwei Kategorien: jene von unten und jene von oben. Beobachter von unten hausen in den laubigen Wildnissen, kümmern sich aber kaum um wellenschneidende Fahrzeuge oder Tauchboote – ihre Augen sind fest himmelwärts gerichtet. Beobachter von oben betrachten das Wilde Blau größtenteils als ihr Zuhause und ärgern sich entweder über die Anwesenheit von Luftschiffen in ihrem Revier oder sehen solche Fahrzeuge als interessante Spielzeuge. Nicht alle Beobachter sind Leviathan-groß (auch wenn einige das durchaus sind), aber alle teilen ein ungewöhnliches Maß an Macht und Zähigkeit, das dem solcher Kreaturen ebenbürtig ist."},
 {h:"Beobachter im Spiel"},
 {a:"Zu Beginn einer Luftreise kann das Glühwürmchen bis zu zwei Beobachter wählen, die entlang der Route aktiv sind, typischerweise einen von oben und einen von unten. Diese Wahl wird im Geheimen getroffen; ein Beobachter kann aus den Vorschlägen ab S. 36 genommen, aus einigen der Gefahren in Kapitel 5 angepasst oder eine ganz eigene Schöpfung sein, die zu den Wünschen und Ängsten des Tischs passt. Rechts findest du ein Beispiel für einen Beobachter."},
 {box:"Die Hungrigen Sterne (Beobachter von oben)", x:["Während die Sterne wie wenig mehr als Lichtpunkte am Nachthimmel wirken mögen, ist für ein geschultes Auge dort etwas anderes. Eine Sehnsucht vielleicht … Oder ein Hunger.","Auferlegter Abzug: Bei Würfen unter den Sternen bei Nacht.","Unmarkiert: Ein leeres Gefühl regt sich in der Crew, wenn die Nacht naht, eine eigentümliche Unruhe, die nichts zu stillen scheint.","Markiert: Im Sternenlicht fällt das Denken schwerer – die Crew vergisst, was sie eben getan hat, und tut sich schwer mit Aufgaben, die sie tausendmal getan hat. Hunger ist eine ständige Ablenkung.","Verbrannt: Hunger greift auf dem ganzen Schiff um sich, selbst unter jenen, die kaum einen Blick auf den Himmel geworfen haben – Krankheiten, Krämpfe und leichte bis schwere Vergiftungen sind häufig. Das Sternenlicht laugt aus und dörrt."]},
 {h:"Beobachtet werden"},
 {a:"Der bloße Akt, beobachtet zu werden, verhängt in bestimmten Situationen Abzug, abhängig von der Art des Beobachters. Ein Abzug von eins genügt meist und wird angewendet, selbst wenn sich die Crew des Einflusses des Beobachters noch nicht bewusst ist. Glühwürmchen müssen keine Einzelheiten dazu geben, warum eine bestimmte Aktion Abzug erhält, wenn sie das Geheimnis des Beobachters wahren wollen."},
 {a:"Beobachter verändern außerdem den Ton einer Reise, je nachdem, ob ihr zugehöriges Wachsames Auge unmarkiert, markiert oder verbrannt ist. Was ist ein Wachsames Auge? Nun …"}
]});
L.push({id:"sr-blau-wachsame-augen", k:K, t:"Wachsame Augen", p:33, q:"sr", b:[
 {a:"Sobald das Luftschiff der Crew den Hafen verlassen hat (oder sich gefährlich von den Wellenspitzen gestartet hat) und das Glühwürmchen entschieden hat, welche Beobachter für die Reise genutzt werden, ist es Zeit, eine Leiste der Wachsamen Augen zu erstellen. Das ist eine besondere Leiste mit zwei Kästchen, die Spieler ihrem Schiffsbogen hinzufügen sollten und die speziell dazu dient, die Aufmerksamkeit zu überwachen, die sie von den vom Glühwürmchen gewählten Beobachtern auf sich gezogen haben. Das oberste Kästchen steht für einen Beobachter von oben und das untere für einen Beobachter von unten."},
 {a:"Hier ein Beispiel, wie diese Leiste für eine Crew aussehen könnte, die nachts in einer für Piratenbanden bekannten Gegend himmelwärts fährt …"},
 {l:["Die Hungrigen Sterne (↑)","Die Portlock-Piraten (↓)"]},
 {a:"Wenn die Crew im obigen Beispiel die ganze Nacht während ihrer Reise aktiv bleibt, zieht sie wahrscheinlich den Zorn der Sterne selbst auf sich. Wenn sie sich auf den Erwerb von Fracht und Ressourcen konzentriert, gerät sie vielleicht an die Portlock-Piraten, eine lokale Plündergruppe, bekannt für ihre eifersüchtige Gier."},
 {h:"Name oder nicht?"},
 {a:"Im obigen Beispiel ist jedes Wachsame Auge nach dem Beobachter benannt, den es verfolgt, aber das muss nicht so sein! Das Glühwürmchen gibt die Namen vielleicht nicht sofort heraus, wenn die Crew sich der möglichen Bedrohung nicht bewusst ist, oder nennt einen falschen Namen, bis sie mehr über die Gefahren erfährt, denen sie sich gegenübersieht."},
 {h:"Informationen sammeln"},
 {a:"Die Crew hat auch die Möglichkeit, Informationen über die Beobachter zu sammeln, die sie auf ihren Luftreisen bedrohen. Das kann als mechanische Belohnung für bestimmte gekürzte Ergebnisse kommen (siehe den Abschnitt rechts für mehr Einzelheiten dazu), aber auch durch kluge Schlussfolgerungen der Spieler oder aktive Untersuchung durch die Crew. Der Name und die Situation, in der ein Beobachter Abzug verhängt, können beide vor den Spielern verborgen bleiben, bis sie genug Informationen gesammelt haben."},
 {a:"Informationen über einen Beobachter könnten sogar in Form von Flüstern zu der Wesenheit oder von Proben kommen, die sie zurücklässt, nachdem sie Schiff oder Crew beeinträchtigt hat."},
 {h:"Die Wachsamen Augen markieren"},
 {a:"Standardmäßig beginnen die Wachsamen Augen eine Himmelsreise unmarkiert – sie sind das Potenzial einer Bedrohung statt ihre Unmittelbarkeit. Doch sobald die Crew beginnt, Aktionen oder Manöver auszuführen, die das Risiko bergen, Aufmerksamkeit auf sich zu ziehen, wächst die Wahrscheinlichkeit, dass etwas Notiz nimmt – das markiert oder verbrennt die Wachsamen Augen, verschlimmert die allgemeine Lage und gibt dem Glühwürmchen die Gelegenheit, zu ungünstigen Zeiten Sand ins Getriebe zu streuen."},
 {h:"Gekürzte Ergebnisse & Aufmerksamkeit erregen"},
 {a:"Sobald die Wachsamen Augen auf dem Bogen stehen, wird Abzug weit wichtiger. Immer wenn ein Spieler bei einem Aktions- oder Wertewurf ein Ergebnis kürzt, hat dieses gekürzte Ergebnis die Chance, Aufmerksamkeit zu erregen. Genauer gesagt zählen die tatsächlichen Ergebnisse, die bei einem Wurf gekürzt werden – das Kürzen eines Triumphs (einer 6) ist für die Crew sogar nützlich, verringert die Aufmerksamkeit und stellt dar, dass die Beobachter ihren Blick anderswohin wenden. Das Kürzen eines Konflikts (einer 5 oder 4) ist weit schlimmer, und das Kürzen eines Desasters (einer 3, 2 oder 1) ist … Nun, eine ganz neue Art von desaströs."},
 {h:"Auf das Niedrige achten"},
 {a:"Wenn du gekürzte Ergebnisse für Aufmerksamkeit prüfst, achte auf das niedrigste aller gekürzten Ergebnisse."},
 {a:"Beispiel: Ein Abzug von zwei bei einer schwierigen Aktion, der die Ergebnisse 6 und 4 entfernt, würde für die Aufmerksamkeit als Kürzen eines Konflikts zählen – das niedrigere Ergebnis."},
 {h:"Welches Auge markieren?"},
 {a:"Wird ein Wurf durch von einem Beobachter verhängten Abzug beeinflusst, gehen alle Markierungen oder Verbrennungen auf das Auge dieses Beobachters. Gibt es keinen verhängten Abzug, der Abzug aber dennoch auf eine Markierung hinausläuft, erhält das passendste Wachsame Auge das Privileg."},
 {a:"Beispiel: Die Crew der Dragonfly’s Spin ist auf dem Weg zu einem fernen Fest, als sie durch die Ausläufer eines Sporensturms fährt. Sie muss einen Wertewurf machen, Neigung, um das Schiff stabil zu halten. Der Wurf endet mit einem Ergebnis von 3 (was für das Schiff ohnehin keine gute Nachricht ist) und einem gekürzten Ergebnis von 5 – einem Konflikt, genug, um die Aufmerksamkeit eines der Wachsamen Augen zu erregen. Sie sind nah an den Wellen, also entscheidet das Glühwürmchen, dass das Auge der Portlock-Piraten das passendste ist – die drastischen Manöver des Schiffs reichen, um deren Aufmerksamkeit zu erregen."},
 {tab:{k:["Niedrigstes gekürztes Ergebnis","Folge"],z:[
  ["6 · Ein Triumph gekürzt – Glückliche Flucht","Ist das niedrigste Ergebnis, das du kürzt, eine 6, hast du es gerade so geschafft, durch deine Aktionen keine Aufmerksamkeit auf dich zu ziehen. Du kannst entweder …"],
  ["6","Eine Markierung von einem beliebigen Wachsamen Auge leeren."],
  ["6","Einen Hauch Information über einen der Beobachter erhalten (vom Glühwürmchen geliefert)."],
  ["5, 4 · Einen Konflikt gekürzt – Aufmerksamkeit erregt","Ist das niedrigste Ergebnis, das du kürzt, eine 5 oder eine 4, hast du ein Mindestmaß an Aufmerksamkeit auf dich gezogen. Du kannst entweder …"],
  ["Ordnung (4–5)","Eines der Wachsamen Augen markieren."],
  ["Ordnung (4–5)","Ein bereits markiertes Wachsames Auge verbrennen."],
  ["Ordnung (4–5)","Einen Hauch Information über einen der Beobachter erhalten (vom Glühwürmchen geliefert), wenn beide Augen bereits verbrannt sind."],
  ["3, 2, 1 · Ein Desaster gekürzt – Volle Aufmerksamkeit","Ist das niedrigste Ergebnis, das du kürzt, eine 3, 2 oder 1, hast du die volle und unmittelbare Aufmerksamkeit eines der Beobachter auf dich gezogen. Du kannst entweder …"],
  ["Natur (1–3)","Eines der Wachsamen Augen verbrennen."],
  ["Natur (1–3)","Einen Hauch Information über einen der Beobachter erhalten (vom Glühwürmchen geliefert), wenn beide Augen bereits verbrannt sind."]
 ]}}
]});
L.push({id:"sr-blau-aufmerksamkeitsfolgen", k:K, t:"Folgen der Aufmerksamkeit", p:34, q:"sr", b:[
 {a:"Die tatsächlichen Auswirkungen von Aufmerksamkeit im Spiel hängen von einer Kombination aus vier Dingen ab …"},
 {l:["Den gewählten Beobachtern","Dem Zustand der Wachsamen Augen","Den von der Crew gesammelten Informationen","Den Aufmerksamkeitsaktionen des Glühwürmchens"]},
 {a:"Die ersten drei davon verschmelzen zu einer bestimmten Atmosphäre für die Reise, wobei der Einfluss der Beobachter auf Ton und Erzählung erweitert wird, wenn die Augen markiert oder verbrannt werden, und verringert (oder zumindest verstanden und abgemildert), wenn die Crew mehr über sie erfährt. Hier einige Beispiele mit den Hungrigen Sternen und den Portlock-Piraten, die den Zustand der Wachsamen Augen jeweils als Referenz zeigen."},
 {h:"Beispiel – Beide unmarkiert"},
 {a:"Der Crew ist ein wachsendes Gefühl von Unbehagen bewusst, wenn die Nacht naht, und an Deck unter den Sternen zu sein, fühlt sich seltsam hohl an. Sie sehen vielleicht auch unbekannte Schiffe in der Ferne, wenn sie nahe den Wellen reisen, oder erspähen Wracks, die von wertvollen Teilen sauber abgeräumt sind und beunruhigend frisch wirken. Sobald sie Informationen über die Beobachter gewinnen, versuchen sie vielleicht, nachts das Deck zu meiden oder in den Wolken statt darunter zu fliegen."},
 {h:"Beispiel – Eine Verbrennung, eine Markierung"},
 {a:"Jeder Abend erfüllt die Crew mit Grauen, und jede Nacht ist ein Spießrutenlauf für das Fahrzeug wie für die Segler darauf. Planken splittern und verblassen, Essbares welkt oder zerfällt zu Staub, und ein alles verzehrender Hunger legt sich über alle an Bord. Der Einfluss der Piraten ist weniger dramatisch, doch jedes Mal, wenn das Schiff unter die Wolkenschicht sinkt, stellt die Crew fest, dass ihr rauchspeiende Schiffe mit greifenden Ladekränen und riesigen Enterkatapulten folgen. Informationen könnten ihnen erlauben, die Macht der Sterne zu verringern, indem sie ihre eigenen Lichter schaffen, oder die Portlocks in schwieriges Gelände zu locken."},
 {h:"Aufmerksamkeitsaktionen"},
 {a:"Bis hierher hatten die Aufmerksamkeitsregeln eine überwiegend erzählerische statt mechanische Wirkung (abgesehen vom zusätzlichen Abzug in Situationen, die mit den gewählten Beobachtern zusammenhängen). Und für manche Tische, manche Crews, ist hier vielleicht der Punkt, es dabei zu belassen – die Effekte der Aufmerksamkeit nicht-mechanisch zu halten, erlaubt gutes Flair und interessante Erfahrungen auf Luftreisen, ein Gegenstück zur Offenheit des Himmels, das helfen sollte zu verdeutlichen, dass er zwar nicht vollgestopft mit Pflanzen ist, aber dennoch eine unergründliche und geheimnisvolle Region."},
 {a:"Doch Glühwürmchen haben die Option, weiterzugehen, in Form von Aufmerksamkeitsaktionen – spezifische negative Effekte, mit denen sie einen Charakter, ein Schiff oder die ganze Crew treffen können, indem sie eine Markierung oder Verbrennung auf einem der Wachsamen Augen leeren."},
 {a:"Das Leeren einer Markierung (oder das Verringern einer Verbrennung auf eine Markierung) gibt einen sofortigen negativen Effekt. Das kann genutzt werden, um einem sonst leichten Reiseabschnitt eine unerwartete Prise Gefahr hinzuzufügen oder eine bereits laufende Szene zu verkomplizieren, indem ein neues Element hinzukommt, mit dem sich die Crew auseinandersetzen muss. Das Leeren einer Verbrennung ist mächtiger und gibt der Crew große Konsequenzen zu bewältigen, die vielleicht eine eigene Szene erfordern."},
 {a:"Die auf den nächsten Seiten aufgeführten Beobachter enthalten jeweils ein paar Vorschläge für spezifische Aufmerksamkeitsaktionen, doch die Listen unten lassen sich an jeden Beobachter anpassen."},
 {c:"Das Glühwürmchen kann eine Markierung leeren, um …", l:["Einem einzelnen Crewmitglied mittleren Schaden zuzufügen","Der gesamten Crew leichten Schaden zuzufügen","Morast zu verursachen oder Ressourcen negative Tags hinzuzufügen","Einen Teil des Schiffs vorübergehend außer Betrieb zu setzen","Die Wucht bestimmter Aktionen für eine Weile zu verringern","Reise- oder Projektleisten negativ zu beeinflussen","Passagiere, Unterbesatzung oder Fracht negativ zu beeinflussen","Den vom jeweiligen Beobachter verhängten Abzug zu erhöhen"]},
 {c:"Das Glühwürmchen kann eine Verbrennung leeren, um …", l:["Einem einzelnen Crewmitglied schweren Schaden zuzufügen","Der gesamten Crew mittleren Schaden zuzufügen","Massenhaft Morast zu verursachen oder bestimmte Ressourcen zu zerstören","Crew, Unterbesatzung oder Passagiere zu verletzen","Dem Schiff ernsten strukturellen Schaden zuzufügen","Bestimmte Fertigkeiten oder Sprachen vorübergehend zu deaktivieren","Schiffswerte oder Aspektleisten zu verbrennen","Den Beobachter als Begegnung das Schiff entern zu lassen"]},
 {h:"Mit Aufmerksamkeit umgehen"},
 {a:"Ob die Effekte der Aufmerksamkeit erzählerisch oder mechanisch sind, die meisten Crews werden sie vermeiden wollen. Hier ein paar Wege, wie sie das tun können …"},
 {c:"Ablenker nutzen", x:"Ablenker sind eine neue luftschiffspezifische Ausstattung, geschaffen, um Aufmerksamkeit zu vermeiden oder Markierungen und Verbrennungen zu leeren, ehe das Glühwürmchen die Chance dazu hat. Eine Liste von Ablenkern findest du auf S. 116, jeder davon kostet Einsätze und alle lassen sich auf mehrere Arten nutzen."},
 {c:"Landen", x:"Manchmal sind die einfachsten Lösungen die besten – eine Reise früh zu beenden oder zu landen und eine Weile über die Wellen zu reisen, kann Beobachter ein Schiff ganz aus den Augen verlieren lassen, Markierungen leeren, Verbrennungen verringern oder die Leiste der Wachsamen Augen vollständig entfernen."},
 {c:"Einen Beobachter konfrontieren", x:"Das ist wahrscheinlich nicht die beste Idee, aber manche Crews werden Beobachter definitiv als Nagel sehen, der eingehämmert werden muss. Manche Beobachter direkt zu konfrontieren ist unmöglich – die Hungrigen Sterne zum Beispiel sind selbst für das bestausgerüstete Luftschiff außer Reichweite. Doch andere, wie die Portlock-Piraten, sind eine greifbare Bedrohung, mit der man sich auseinandersetzen und die man vielleicht sogar zurückschlagen kann.\nDas Wort „zurück“ ist hier wichtig – die Beobachter sind standardmäßig nicht vollständig zu besiegen (auch wenn der Versuch, es zu tun, ein großartiger Kampagnenkeim sein könnte). Sie zu überwinden, könnte eines der Wachsamen Augen für eine Reise oder sogar ein paar Reisen leer lassen, doch die Beobachter werden immer einen Weg finden, ihr Revier wieder in die Hand zu bekommen und mit Rachedurst zurückzukehren.\nDieser Ansatz erfordert ein erfahrenes Glühwürmchen, da die Beobachter keine Gefahren-Einträge haben, auf die es sich für zusätzliche Informationen stützen kann."}
]});
L.push({id:"sr-blau-aufmerksamkeit-spiel", k:K, t:"Aufmerksamkeit im Spiel", p:35, q:"sr", b:[
 {bsp:"Aufmerksamkeit im Spiel", z:[
  ["Glühwürmchen","Die Sonne sinkt unter den Horizont, während ihr wartet, aber gnädigerweise verklingen die Geräusche der Verfolgung in der Ferne. Dein Schachzug hat funktioniert, Inge – die Plünderer sind lange weg."],
  ["Inge","Und das ohne Kampf!"],
  ["Todd","Okay, vielleicht war es ein anständiger Plan. Aber wir hätten sie trotzdem erledigen können, finde ich."],
  ["Laura","Ja, hätten wir, aber ich bin froh, dass wir es nicht mussten. Ich sage, wir geben es noch eine Stunde oder so, um sicherzugehen, und starten dann wieder – wir sind angeschlagen genug, dass ich jetzt lieber fliegen als wellenschneiden würde, und wir haben genug von unseren Werten übrig, um die Startkosten zu schlucken."],
  ["Glühwürmchen","Vernünftig. Wer ist diesmal am Steuer?"],
  ["Todd","Im Spiel wäre ich etwas mürrisch, weil wir den Kampf verpasst haben. Außerhalb des Spiels, Inge, das war großartig – du solltest uns diesmal hochbringen, die Serie weiterführen."],
  ["Inge","Aww, danke! Mach ich, ja. Muss ich für den Start würfeln?"],
  ["Glühwürmchen","Nein, die Baumwipfel sind hier glatt genug, dass du ohne große Mühe in die Luft kommst – abgesehen von ein paar Schrammen und dem üblichen Werte-Treffer."],
  ["Inge","Das trage ich ein, und ich denke, wir schneiden auch für das erste Stück der Reise einen Pfad – bleiben wir vorsichtig. Wer ist auf Wache?"],
  ["Kyllian","Ich mache das, kein Problem."],
  ["Glühwürmchen","Nun, Kyllian, bevor du für diese Wache würfelst, bemerkst du etwas Seltsames. Als du dich an Deck einrichtest, fühlt sich die Nacht weniger ruhig an, als sie sollte – du kannst es dir nicht bequem machen, egal wie du sitzt, und deine Finger zucken über deinen Besitztümern."],
  ["Kyllian","Das ist … weniger als großartig?"]
 ]},
 {bsp:"Aufmerksamkeit im Spiel, Fortsetzung", z:[
  ["Glühwürmchen","In der Tat, und du bist nicht der Einzige. Zeichnet die Leiste der Wachsamen Augen auf eurem Schiffsbogen, nur zwei verbundene Kästchen. Beide sind zu Beginn unmarkiert."],
  ["Laura","Ohh, es gibt Beobachter. Das ist neu für mich, glaube ich. Wie nennen wir die Leisten?"],
  ["Glühwürmchen","Noch keine Namen, aber Laura – Kyllian ist nicht der Einzige, der die Auswirkungen spürt. Wo im Schiff bist du?"],
  ["Laura","In meiner Kabine, wahrscheinlich, sobald wir in der Luft sind."],
  ["Glühwürmchen","In den ersten Minuten der Reise fängst du aus dem Kabinenfenster einen Lichtschimmer von den Wellen unten ein. Signallaternen, wie es aussieht – sprichst du fließend Signalsprache?"],
  ["Laura","Nein … Aber ich wünsche mir wirklich, es zu tun. Flieg uns sicher, Inge … Ich habe ein ungutes Gefühl dabei."]
 ]}
]});
L.push({id:"sr-blau-beobachter-oben", k:K, t:"Beobachter von oben", p:36, q:"sr", b:[
 {erz:"Halikos Enterhaken hing über der Reling, das Seil zweimal herumgewickelt. Es war eine größere Sicherheitsvorkehrung, als die meisten für Rumpfarbeiten getroffen hätten, selbst hier oben. Dennoch konnte er nicht anders, als sich unwohl zu fühlen, als er sich über die Kante des Schiffs in den Sturm hinabließ.\nDer Wind zerrte an seiner Kleidung wie die Hände eines Bettlers. Er hatte keine Zunge, um die Luft zu schmecken, doch die Chitin-Streben zwischen seiner inneren und äußeren Schale waren empfindlich genug, um wie eine zu wirken – die Himmel troffen von wahrscheinlichem Blitz.\nWorte von oben. Eine Warnung oder Ermutigung? So oder so spielte es kaum eine Rolle. Wenn er nicht herausfand, was den Motor gestoppt hatte, würden sie alle bald Ruhe unter den Wellen finden."},
 {h:"Beobachter von oben"},
 {a:"Das Glühwürmchen hat drei Optionen, wenn es wählt, welche Beobachter eine Luftreise beeinflussen; es kann einen Gefahren-Eintrag aus Kapitel 5 nehmen und als Grundlage für eine einzigartige Bedrohung nutzen, es kann etwas von Grund auf erschaffen, das perfekt zum Reich oder Territorium passt, durch das die Crew reist, oder es kann aus den Beispiel-Beobachtern auf den folgenden Seiten wählen. Für das erste Mal mit dem Aufmerksamkeitssystem ist wahrscheinlich der letzte Ansatz der beste – die hier vorgestellten Beobachter lassen sich für die Mehrheit himmelsbasierter Umgebungen nutzen oder anpassen. Die unten gezeigte Struktur kann Glühwürmchen auch helfen, wenn sie während einer Luftreise ihre eigenen Beobachter erschaffen und einsetzen."},
 {c:"Die Hungrigen Sterne (Beobachter von oben)", x:"Während die Sterne wie wenig mehr als Lichtpunkte am Nachthimmel wirken mögen, ist für ein geschultes Auge dort etwas anderes. Eine Sehnsucht vielleicht … Oder ein Hunger.\nAuferlegter Abzug: Bei Würfen unter den Sternen bei Nacht.\nUnmarkiert: Ein leeres Gefühl regt sich in der Crew, wenn die Nacht naht, eine eigentümliche Unruhe, die nichts zu stillen scheint.\nMarkiert: Im Sternenlicht fällt das Denken schwerer – die Crew vergisst, was sie eben getan hat, und tut sich schwer mit Aufgaben, die sie tausendmal getan hat. Hunger ist eine ständige Ablenkung.\nVerbrannt: Hunger greift auf dem ganzen Schiff um sich, selbst unter jenen, die kaum einen Blick auf den Himmel geworfen haben – Krankheiten, Krämpfe und leichte bis schwere Vergiftungen sind häufig. Das Sternenlicht laugt aus und dörrt.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, damit alle essbaren Ressourcen eines einzelnen Charakters den Tag Verwelkt, Verdorben oder Verrottet erhalten.","Eine Markierung leeren, damit sich ein Gefährte gegen seinen Besitzer wendet, ihm direkt Schaden zufügt und dabei selbst gleichzeitig Schaden nimmt.","Eine Verbrennung leeren, damit einer der Räume des Schiffs von außen völlig einstürzt, den Himmeln ausgesetzt und fast unbenutzbar wird."]},
 {c:"Nyr (Beobachter von oben)", x:"Nicht alle sterblichen Ängste kommen in Leviathan-Größe, und nicht jede Legende trägt den Makel der Übertreibung. Nyr ist genau so, wie Aeronauten ihn beschreiben – eine einzigartige Kreatur, eine Fledermaus nicht von gewaltiger Größe, sondern von grenzenloser Wildheit.\nAuferlegter Abzug: Bei Würfen innerhalb des Schiffs oder zum Lauschen.\nUnmarkiert: Wildsegler mit empfindlichen Ohren können die hohen Sonarimpulse von etwas aufschnappen, das zwischen den Wolken jagt, oder so hoch, dass es unsichtbar ist.\nMarkiert: Schwärme anderer Luftkreaturen, von Vögeln über Pteranha bis zu Insekten, fliehen am Schiff vorbei zur relativen Sicherheit der Wellen. Kopf- und Ohrenschmerzen in der Crew sind häufig.\nVerbrannt: Nyr hat das Schiff als würdiges Ziel erkannt und schreit Herausforderungen oder Warnungen, die den Geist durchbohren. Findet es den richtigen Moment, stürzt die Kreatur herab, nutzt Wolken oder Dunkelheit als Deckung und reißt mit Klauen und Zähnen Stücke aus dem Fahrzeug.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, um ein einzelnes Crewmitglied zu betäuben oder zu desorientieren und leichten Explosions-Schaden zuzufügen.","Eine Markierung leeren, damit lebende Fracht sich losreißt.","Eine Markierung leeren, damit Nyr vorbeifliegt, am Schiff reißt und zwei Werte auf einmal beschädigt.","Eine Verbrennung leeren, damit ein Passagier oder Mitglied der Unterbesatzung in Wahnsinn oder bebende Furcht getrieben wird.","Eine Verbrennung leeren, damit Nyr ins Schiff einbricht, durch die Korridore streift und sich durch Türen und Wände drängt. Nyrs Wunden schließen und vernarben in Sekunden, was Morast verursacht, doch der Kreatur genug Schaden zuzufügen, könnte sie zum Rückzug zwingen."]}
]});
L.push({id:"sr-blau-beobachter-oben-2", k:K, t:"Himmelszahnräder & Geister-Aeroviathan", p:37, q:"sr", b:[
 {c:"Die Himmelszahnräder (Beobachter von oben)", x:"Ein abgerutschtes Schwungrad oder eine falsch ausgerichtete Lochkarte ist meist Quelle einfacher mechanischer Fehler in Ordinatoren und komplexen Maschinen, besonders in jenen ohne einen Faden Seele zur Selbstkorrektur. Doch für die Himmelszahnräder summieren sich diese kleinen Fehler, bilden mechanische Geister und lassen sie zerbrechen, ehe sie sie in eine seltsam logische pseudoreligiöse Inbrunst treiben – wenn die Himmel (sollten gewisse vorverdante Texte stimmen) der Wohnsitz des Göttlichen der alten Welt sind, dann deutet dessen Abwesenheit in der Welt auf einen unbesetzten Thron.\nAuferlegter Abzug: Bei Würfen zum Erforschen, Lernen oder Studieren sowie beim Reparieren oder Verändern von Mechanismen.\nUnmarkiert: Signalanlagen an Bord blinken zufällig, Lichter flackern und Mechanismen regen sich unbändig. Der Nachthimmel wird gelegentlich von Ausbrüchen schnellen Signalisierens unsichtbarer Schiffe erhellt, fast zu schnell, um sie zu deuten, doch ein sorgfältiger Beobachter wird Fragen herauspicken, die an den Himmel selbst gerichtet scheinen.\nMarkiert: Klobige, nüchterne Luftschiffe hängen bewegungslos am Horizont, scheinbar von gebändigtem Magnetismus in der Luft gehalten. Signalanlagen werden fast völlig unzuverlässig. Ironbound- und Corron-Wildsegler spüren ein tiefes Gefühl, dass etwas völlig falsch ist.\nVerbrannt: Maschinen an Bord des Luftschiffs beginnen zu glitchen, zu springen und zu versagen, und das Schiff (wenn es kann) sendet trotz aller Bemühungen der Crew ständig einladende Signale aus. Jene fernen Schiffe treiben näher – sie haben alle Zeit der Welt.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, um das Schiff aus großer Entfernung mit präzisem Kanonenfeuer zu treffen und Strom- oder Explosions-Schaden zuzufügen.","Eine Markierung leeren, damit eine Maschine oder ein Schiffssystem kaputtgeht oder versagt.","Eine Markierung leeren, damit Signalausrüstung ein Crewmitglied hypnotisiert oder verwirrt.","Eine Verbrennung leeren, damit sich eine Maschine an Bord losreißt und die Crew angreift.","Eine Verbrennung leeren, damit die schwebenden Schiffe einen Enterertrupp aus Konstrukt-Piraten schicken, deren Ziel es ist, das Schiff von allem zu befreien, was Auftrieb, Treibstoff oder mehr Höhe geben könnte."]},
 {c:"Geister-Aeroviathan (Beobachter von oben)", x:"Luft-Leviathane haben meist weit kürzere Lebensspannen als ihre wellenbewohnenden Gegenstücke, halten sich aber auch eher über den Tod hinaus irgendwie fest. Ein Ghast-Leviathan (oder technisch eher „Aeroviathan“, wie es im Himmelsjargon heißt) ist ein massiver Geist, an seine alten Knochen verankert, meist wie ein makabrer Satz knöcherner Wolken durch die obere Luft treibend. Ironisch vielleicht, dass die Anwesenheit von so viel Tod so viel Pseudoleben hervorbringen kann, aber es ist keine Ironie, die viele Crews innehalten und würdigen können.\nAuferlegter Abzug: Bei Würfen zur Interaktion mit Geistern oder spirituellen Präsenzen.\nUnmarkiert: Es gibt einen Anstieg spiritueller Energie, genug, dass Ardent mit den Zähnen knirschen und Anchored erschaudern. Die Quelle ist unmöglich zu verorten, aber es muss etwas von gewaltiger Größe sein.\nMarkiert: Geister kreuzen den Weg des Schiffs wie lautlose Wale, Andeutungen von Gliedern, Flügeln und Flossen, die Fahrzeuge in ihrem Kielwasser fangen.\nVerbrannt: Geisteraugen füllen Bullaugen, und Türen öffnen sich zu längst toten Magenhöhlen. Das Schiff knarrt wie alte Knochen, müht sich zu steigen und zu wenden, riecht wie eine Himmelsbestattung. Das Schiff teilt das Wilde Blau jetzt nicht nur mit Geistern; es ist von ihnen durchdrungen.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, um einem Crewmitglied mittleren Salz-Schaden zuzufügen und sofort seine Erinnerung an das Ereignis zu löschen.","Eine Markierung leeren, damit die Temperatur im Inneren des Schiffs für kurze Zeit auf gefährliche Werte sinkt.","Eine Markierung leeren, um zwei verschiedenen Crewmitgliedern Morast zuzufügen, die jeweils dieselbe spektrale Präsenz an verschiedenen Orten sehen.","Eine Markierung leeren, damit ätherische Strömungen das Schiff vom Kurs werfen und eine Markierung auf der Reiseleiste leeren.","Eine Verbrennung leeren, um einem Crewkameraden schweren Salz-Schaden zuzufügen, während sein Geist versucht, aus seiner Haut zu entkommen.","Eine Verbrennung leeren, damit ein Teil des Schiffs seine Greifbarkeit verliert und durchscheinend und unzuverlässig wird.","Eine Verbrennung leeren, damit ein Geister-Aeroviathan das Schiff angreift und massiven Salz- und Stumpf-Schaden zufügt."]},
 {bsp:"Aufmerksamkeitsaktionen im Spiel", z:[
  ["Glühwürmchen","Mit jeder Minute, die ihr reist, wird das Gefühl schlimmer. Ihr wisst, dass es jetzt die Sterne sind, ihr müsst es also nur bis zum Morgen aussitzen, aber wie schützt ihr euch vor dem Schlimmsten?"],
  ["Todd","Ich bin mit Wache dran, also bleibe ich an Deck, aber ich behalte die Wellen im Auge – lieber sehe ich diese Schiffe unter uns als diesen verdammten Himmel."],
  ["Inge","Und ich fand den Nachthimmel immer so hübsch … Ich bin noch am Steuer, also kann ich nicht viel tun, außer ich will die Augen schließen und uns vom Kurs bringen."],
  ["Glühwürmchen","Aber der Steuerstand ist zumindest geschlossen – da ist Bernsteinglas zwischen dir und dem Sternenlicht."],
  ["Kyllian","Ich bin draußen an Deck und versuche, etwas herzustellen, irgendein Gebräu, das unsere Sinne dämpfen könnte. Ich würfle mit Schleier und Brauen und nutze mein Milchkraut und meine Crezzerin-Tinte. Gibt es dafür Abzug?"],
  ["Glühwürmchen","Es wird definitiv Abzug geben, aber als du deine Zutaten herausholst, merkst du, dass etwas gewaltig schiefgelaufen ist. Ich leere eine Markierung auf dem Beobachter von oben, den Sternen, um eine Aufmerksamkeitsaktion zu nutzen. Kyllian, alle deine essbaren Ressourcen haben jetzt die Tags Verrottet oder Verwelkt, fürchte ich."],
  ["Kyllian","Oh, verdammt noch mal! Die Tinte ist dann in Ordnung, aber das Milchkraut wird verwelkt sein … Und so viel anderes, das ich mir noch gar nicht ansehe. Ich nehme an, das ist ein Abzug für das Sternenlicht und ein weiterer für das verwelkte Milchkraut?"],
  ["Glühwürmchen","Genau."],
  ["Kyllian","Oh … Oh nein … Das ist eine 1, eine 1, eine 2 und eine 4. Ein Desaster mit einer Wendung. Mit aktiver Aufmerksamkeit …"],
  ["Glühwürmchen","Ja, das ist nicht gut. Das Auge, das ich eben geleert habe? Ich verbrenne es. Es wird gleich schlimm …"]
 ]}
]});
L.push({id:"sr-blau-beobachter-unten", k:K, t:"Beobachter von unten", p:38, q:"sr", b:[
 {a:"Ebenso sehr eine Bedrohung wie jene von oben werden Beobachter von unten von den unerwarteten Punkten aus Licht und Leben angezogen, die darüber ziehende Schiffe darstellen. Wie bei den Beobachtern auf der vorigen Seite sind diese spezifischen Beispiele als Ergänzung zur Anpassung von Gefahren aus Kapitel 5 gedacht oder zu den eigenen Schöpfungen des Glühwürmchens, zugeschnitten auf die Besonderheiten einer Reise."},
 {c:"Coalflower Jin (Beobachter von unten)", x:"Petalsquid sind in den Tiefen kein ungewöhnlicher Anblick, wobei Tauchfahrer Varianten von Katzen- bis Protoleviathan-Größe aufgezeichnet haben. Doch es gibt einen, eine einzigartige Wesenheit, der nur in versengten Logbüchern von Aeronauten und den betrunkenen Tiraden schwer bandagierter Kapitäne auftaucht – Coalflower Jin.\nAuferlegter Abzug: Bei Würfen für Flugmanöver.\nUnmarkiert: Die Motoren des Luftschiffs rattern und würgen und erzeugen Schübe von Rauch und Dampf, ganz gleich, wie sie gebaut sind oder welchen Treibstoff sie nutzen.\nMarkiert: Manöver und Flugmanöver fühlen sich träge an, und das Schiff neigt dazu, im Flug zu einer Seite zu krängen, obwohl Ballast und Gewichtsverteilung normal wirken. Das Innere des Schiffs wird heißer und heißer, selbst in den kältesten Himmeln.\nVerbrannt: Jin steigt aus den Wellen unten auf, Blätter in seinem Kielwasser schwelend, obwohl sein eigener Körper und seine Blüten völlig unberührt scheinen. Es jettet lautlos durch die Himmel im Kielwasser des Schiffs, und jedes Mal, wenn es näher kommt, steigt die Hitze.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, um einem Crewkameraden leichten oder mittleren Flammen-Schaden zuzufügen und eine seiner Ressourcen in Brand zu setzen.","Eine Markierung leeren, um ein Element des Luftschiffs zu überhitzen, alles vom Rauminhalt über das Motorgehäuse bis zum Steuerrad des Schiffs.","Eine Verbrennung leeren, damit Coalflower Jin das Schiff direkt angreift, massiven Flammen-Schaden zufügt und mehrere Brände entfacht."]}
]});
L.push({id:"sr-blau-beobachter-unten-2", k:K, t:"Nautico, Hirschwoge & Hexenmaulwürfe", p:39, q:"sr", b:[
 {c:"Die Nautico (Beobachter von unten)", x:"Ein spektrales Tauchboot, das aus den Tiefen aufsteigt, verankerte Crew überzeugt, dass der einzige Weg, der Dunkelheit zu entkommen, darin besteht, mit den Lebenden den Platz zu tauschen.\nAuferlegter Abzug: Bei Würfen innerhalb der Räume und Korridore des Luftschiffs.\nUnmarkiert: Die Crew spürt vielleicht die traditionellsten Anzeichen eines Spuks – eine überwältigende Kälte, ein Flackern der Lichter im Schiff und das Gefühl, beobachtet zu werden, ohne zu wissen, woher. Albträume von laubiger Dunkelheit sind häufig, verblassen aber beim Erwachen.\nMarkiert: Die Nautico taucht auf, ein zerstörtes Tauchboot in Silber und Schatten. Das Luftschiff lässt es vielleicht auf seiner Reise hinter sich, nur um wenige Augenblicke später wieder darüber zu fliegen. Die ungewöhnlichen Vorkommnisse an Bord nehmen zu, und die Wildsegler sind unsicher, ob das, was sie erleben, das Ergebnis von Halluzination oder spektralem Angriff ist.\nVerbrannt: Das Tauchboot steigt über die Wellen auf, segelt mit erschreckender Stille durch die Himmel und hält auf das Luftschiff zu. Das Ziel der verlorenen Segler der Nautico ist nicht zu töten, sondern die Plätze zu tauschen – sie werden entführen, wenn sie können, und gefangene Charaktere und Unterbesatzung im sporenerfüllten Inneren ihres Tauchboots einschließen.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, um den Bewohnern eines Raums oder Korridors Frost- oder Gift-Schaden zuzufügen.","Eine Markierung leeren, damit die Proben eines Wildseglers wachsen und sich winden und den Tag Wiedergänger erhalten.","Eine Markierung leeren, um einem einzelnen Charakter zwei Markierungen Morast aufzuerlegen, während er den vernarbten Rumpf der Nautico erblickt.","Eine Verbrennung leeren, damit das Tauchboot ins Luftschiff kracht und Werte oder interne Struktur beschädigt.","Eine Verbrennung leeren, damit die Nautico spektrale Plünderer ausspeit, die sich in Sporenwolken bewegen – diese greifen die Crew an und verseuchen ihr Luftschiff und versuchen, wenn möglich, Crew über Bord zu zwingen."]},
 {c:"Die Hirschwoge (Beobachter von unten)", x:"Etwas zwischen Bestie, Geist und Naturgewalt, ein Schwarm Geweihe, die nach dem Sonnenlicht greifen, das ihnen durch ihre Zeit in den Tiefen verwehrt blieb.\nAuferlegter Abzug: Bei Würfen zum Jagen lebender Kreaturen oder Sammeln wachsender Pflanzen.\nUnmarkiert: Ein Duft aus Blut und Samt liegt über dem Deck, und die Crew spürt unerwartete Energie. Das Gestrüpp unten scheint beweglicher als üblich, Wellenspitzen-Äste krachen so hart aneinander, dass sie splittern und brechen.\nMarkiert: Die Woge zeigt sich, eine formlose Welle aus knochenweißen Geweihen, die über die Baumwipfel purzelt. Fliegende Säugetiere in der Gegend werden zunehmend feindselig (egal, wie groß sie sind oder wie friedfertig sonst).\nVerbrannt: Die Woge entkommt den Wellenspitzen und schraubt sich wie ein leichenhafter Trichter in den Himmel, in ständiger Verfolgung von Schiff und Crew. Selbst wenn sie zurückgeschlagen wird, kann die Woge Fragmente ihrer selbst zurücklassen, spinnenartige Geweihgruppen, die durch die Räume eines Schiffs schleichen und auf ihren Moment warten.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, um ein Crewmitglied zu zwingen, eine bizarre Projektleiste mit Proben und Bergegut zu beginnen.","Eine Markierung leeren, damit fliegende Säugetiere die Crew an Deck angreifen und allen Betroffenen leichten Stumpf-Schaden zufügen.","Eine Verbrennung leeren, damit die Woge hochschnellt und über dem Schiff zusammenbricht und sowohl Werten als auch Crew gleichzeitig Schaden zufügt.","Eine Verbrennung leeren, damit die Woge sich zurückzieht, aber das Schiff mit beweglichen Raubgeweihen befällt (erstelle eine Leiste – das Finden und Zerstören eines füllt ein Kästchen, sie schlagen weiter zufällig zu, bis die Leiste gefüllt ist)."]},
 {c:"Hexenmaulwürfe (Beobachter von unten)", x:"Sternnasenmaulwürfe von der Größe von Bären, deren arconautische Organe darauf ausgerichtet sind, die Schwerkraft selbst als Werkzeug für Jagd und Spiel zu waffnen.\nAuferlegter Abzug: Bei Würfen zur Interaktion mit schweren Gegenständen und Fracht und für präzise Manöver.\nUnmarkiert: Eine Schar Hexenmaulwürfe kommt aus den unteren Tiefen, um eine Weile im Regen zu schwelgen. Aufmerksame Segler bemerken vielleicht, dass die Tröpfchen um sie herum beim Fallen in ungewöhnlichen Mustern abbiegen, und vielleicht gelegentliches Rucken an den Rudern oder der Steuersäule des Luftschiffs.\nMarkiert: Die Hexenmaulwürfe sehen das vorbeiziehende Luftschiff als Spielstein in einem Spiel, ziehen und stoßen es mit Peitschen arconautisch veränderter Schwerkraft. Das könnte Segler von Wand zu Wand schleudern, das Schiff auf den Kopf drehen oder es für kurze Zeit nach oben fallen lassen.\nVerbrannt: Das Spiel wird zur Jagd. Die Hexenmaulwürfe ziehen sich unter das Gestrüpp zurück, doch sie haben die Fährte des Schiffs – an jedem Punkt seiner Reise könnte es sich brutal zu den Wellen hinabgerissen, durch eine Verschiebung natürlicher Kräfte vom Kurs gezogen oder zum Ausweichen oder Umgehen eines aufwärts fallenden Schauers aus Ästen, Steinen und kleinen Tieren gezwungen finden.\nAufmerksamkeitsaktionen:", l:["Eine Markierung leeren, um der Reiseleiste eine Markierung hinzuzufügen oder zu entfernen, während die Hexenmaulwürfe launisch spielen.","Eine Markierung leeren, um die Wucht des nächsten Manövers des Schiffs zu senken oder einen plötzlichen Höhenwechsel zu erzwingen.","Eine Verbrennung leeren, um das Schiff in eine unerwartete und katastrophal schädliche Landung zu zerren (woraufhin die Hexenmaulwürfe für den Rest der Reise zurück in die Tiefen zerstreuen)."]},
 {box:"Langjährig oder lange abwesend?", x:["Nicht jede Reise braucht ein völlig neues Paar Beobachter, mit dem sich die Crew auseinandersetzen muss. Sie könnten im Verlauf einer Kampagne mehrmals von denselben Wesenheiten beobachtet werden (besonders, wenn die Begegnungen eine Bedeutung für die Geschichte haben oder wenn sie wiederholt über dieselben Territorien fliegen), oder eines der Wachsamen Augen könnte inaktiv sein, einfach weil kein Beobachter in der Nähe ist, der Interesse nehmen würde (vielleicht wegen der Wahl einer bestimmten Route oder des Folgens einer bestimmten Seekarte)."]}
]});
})(WS_NACH.regeln);
